(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c72"]=[{"id":"00009544","register_sub_id":"101","register_pk":"194337","name":"多田家住宅隠居屋","kana":"ただけじゅうたくいんきょや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県朝倉郡筑前町森山字耳取417-1","lat":33.4526014,"lng":130.62270815,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積94㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0087","desc":"主屋北東に雁行して建ち、木造二階建、建築面積九四平方メートル、入母屋造桟瓦葺である。下階は仏間を備えた座敷とし、仏壇脇に花頭窓を穿つ。上階は座敷と書斎からなり、数寄屋風を加味した意匠とする。上下階とも周囲に縁と庇を廻らし、ガラス窓を建てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009544"},{"id":"00009551","register_sub_id":"101","register_pk":"194344","name":"多田家住宅器蔵","kana":"ただけじゅうたくうつわぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県朝倉郡筑前町森山字耳取417-1","lat":33.45263519,"lng":130.62284521,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積37㎡、渡廊下付","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0094","desc":"隠居屋東面に、太鼓橋状の渡廊下を介して東西棟で建つ。土蔵造二階建、桁行七・六メートル梁間四・八メートル、切妻造桟瓦葺である。外壁は漆喰塗で腰を海鼠壁とし、南面に上下二箇所ずつ窓を穿つ。什器類を収めた土蔵で、主庭の景観を引き立てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009551"},{"id":"00009556","register_sub_id":"101","register_pk":"194349","name":"多田家住宅裏門","kana":"ただけじゅうたくうらもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県朝倉郡筑前町森山字耳取417-1","lat":33.45259775,"lng":130.62306373,"geo_status":"db","era":"明治5年頃","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造、瓦葺、間口2.1m","structure_material":"木造","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0099","desc":"敷地東辺中央に建ち、潜戸付きの板戸を両開きに吊る。間口二・一メートルの薬医門形式で、切妻造桟瓦葺とする。屋敷地前面を通る日田街道が、明治初年までは当門の位置を通過していたとする由緒に因む門で、屋敷地の変遷を伝える記念的意味を持つ裏門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009556"},{"id":"00009555","register_sub_id":"101","register_pk":"194348","name":"多田家住宅表門","kana":"ただけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県朝倉郡筑前町森山字耳取417-1","lat":33.45243294,"lng":130.62237884,"geo_status":"db","era":"明治24年頃","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造、瓦葺、間口2.9m、潜戸付","structure_material":"木造","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0098","desc":"敷地南面に通りからやや後退して建つ。桁行二・九メートル梁間一・七メートルの薬医門形式で、切妻造桟瓦葺とし、西側に潜戸を開く。親柱は正面側半分を花崗岩の石柱、背面側を木柱として冠木を受ける独特なつくりの表門で、風格のある表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009555"},{"id":"00009557","register_sub_id":"101","register_pk":"194350","name":"多田家住宅勝手門","kana":"ただけじゅうたくかってもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県朝倉郡筑前町森山字耳取417-1","lat":33.45272656,"lng":130.62306365,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、瓦葺、間口2.0m","structure_material":"木造","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0100","desc":"敷地東辺の北寄り、的場と物置の間に建つ。間口二・〇メートルの腕木門形式で、柱間に板戸を両開きに吊る。屋根は切妻造桟瓦葺とし、東面屋根には左桟瓦を葺く。南北面に付属する土塀も左桟瓦を葺いており、地方的特色のある屋敷景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009557"},{"id":"00009550","register_sub_id":"101","register_pk":"194343","name":"多田家住宅北ノ蔵","kana":"ただけじゅうたくきたのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県朝倉郡筑前町森山字耳取417-1","lat":33.4527613,"lng":130.62266675,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積22㎡","structure_material":"土蔵造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0093","desc":"隠居屋後方に南北棟で建つ。土蔵造平屋建、桁行五・六メートル梁間四・〇メートル、切妻造桟瓦葺で西面に戸口を設ける。布石積基礎上に建ち、外壁は漆喰塗で隅部のみ腰に瓦を貼る。東面に高窓を穿ち、銅扉を開く。弓道場とともに、良質な屋敷景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009550"},{"id":"00009552","register_sub_id":"101","register_pk":"194345","name":"多田家住宅弓道場","kana":"ただけじゅうたくきゅうどうじょう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県朝倉郡筑前町森山字耳取417-1","lat":33.45274465,"lng":130.62275241,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0095","desc":"北ノ蔵東隣に東面して建つ。木造平屋建、桁行五・〇メートル梁間四・三メートル、切妻造桟瓦葺で、三面に庇を廻らせ、南東面にガラス窓を建てる。内部は北半を板敷の射場とし、南側に四畳の控えを配し神棚を祀る。屋敷地内に残る軽快なつくりの弓道場である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009552"},{"id":"00009549","register_sub_id":"101","register_pk":"194342","name":"多田家住宅材木蔵","kana":"ただけじゅうたくざいもくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県朝倉郡筑前町森山字耳取417-1","lat":33.45265006,"lng":130.62214743,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"土蔵造一部木造平屋建、瓦葺、建築面積102㎡","structure_material":"土蔵造一部木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0092","desc":"敷地西辺北端に南北棟で建ち、南半を土蔵造平屋建の材木置場、北半を木造平屋建の薪置場とする。屋根は段違いの切妻造桟瓦葺とし、東面に下屋を設ける。外壁は材木置場を漆喰塗及び海鼠壁とし、薪置場は中塗仕上げとする。背面側の屋敷景観を整える大型の蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009549"},{"id":"00009542","register_sub_id":"101","register_pk":"194335","name":"多田家住宅主屋","kana":"ただけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県朝倉郡筑前町森山字耳取417-1","lat":33.45249671,"lng":130.62255587,"geo_status":"db","era":"明治23年","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積337㎡","structure_material":"木造平屋一部2階建","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0085","desc":"敷地中央に南面し、木造平屋一部二階建、入母屋造桟瓦葺である。西側を高い吹抜けの土間とし、床上部は居室を二列並べ、東列南面に一〇畳座敷を張出して鍵座敷型に配置する。外観は南西面を漆喰で塗込め重厚な外観とする。風格ある構えの大規模民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009542"},{"id":"00009548","register_sub_id":"101","register_pk":"194341","name":"多田家住宅倉庫","kana":"ただけじゅうたくそうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県朝倉郡筑前町森山字耳取417-1","lat":33.45257511,"lng":130.62217956,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積26㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0091","desc":"納屋西側、材木蔵の南側に南北棟で建つ。木造二階建、桁行五・三メートル梁間五・〇メートル、切妻造桟瓦葺で、東面を下屋とする。昭和二〇年頃まで使用人住居として使用されたため、二階窓に格子を建てる。旧家の暮らしぶりを伝える倉庫である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009548"},{"id":"00009559","register_sub_id":"101","register_pk":"194352","name":"多田家住宅土塀","kana":"ただけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県朝倉郡筑前町森山字耳取417-1","lat":33.45277887,"lng":130.62289724,"geo_status":"db","era":"昭和8年頃／昭和中期改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、瓦葺、総延長106m","structure_material":"木造","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0102","desc":"主屋南東側の一郭や、敷地北東側の附属屋の間に折曲がりにのびる土塀で、総延長一〇六メートルを測る。木造、切妻造桟瓦葺で、屋根に左桟瓦を葺く。布石基礎上に建ち、壁は漆喰塗で腰を杉皮張や簓子下見板張とする。落ち着いた風情のある屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009559"},{"id":"00009546","register_sub_id":"101","register_pk":"194339","name":"多田家住宅長蔵","kana":"ただけじゅうたくながくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県朝倉郡筑前町森山字耳取417-1","lat":33.45274167,"lng":130.6224294,"geo_status":"db","era":"江戸末期／明治24年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積159㎡","structure_material":"土蔵造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0089","desc":"主屋北辺西寄りに東西棟で建つ長大な蔵。土蔵造平屋建、桁行二三・二メートル梁間六・九メートル、切妻造桟瓦葺で、南面二箇所に戸口を設ける。外壁は漆喰塗で腰を海鼠壁とし、南面上部に小窓を穿つ。敷地内で最古の建物として、往時の屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009546"},{"id":"00009547","register_sub_id":"101","register_pk":"194340","name":"多田家住宅納屋","kana":"ただけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県朝倉郡筑前町森山字耳取417-1","lat":33.45253347,"lng":130.62225689,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0090","desc":"主屋北西に広がる裏庭に北面して建つ。木造平屋建、桁行一〇・一メートル梁間一・九メートル、片流招屋根付、桟瓦葺である。南面は、東西にのびる土塀と一連の意匠とし、北面は一部を板壁とする。内部を東西四室に間仕切り、東端を便所とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009547"},{"id":"00009543","register_sub_id":"101","register_pk":"194336","name":"多田家住宅離れ及び渡廊下","kana":"ただけじゅうたくはなれおよびわたりろうか","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県朝倉郡筑前町森山字耳取417-1","lat":33.45242437,"lng":130.62279953,"geo_status":"db","era":"明治35年","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積100㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0086","desc":"主屋南東隅から敷地南辺沿いに渡廊下をのばし、太鼓橋を介して離れに接続する。離れは木造平屋建、寄棟造桟瓦葺で、庭側は縁高欄を廻らし、南面は広縁から集落を見晴らす。主室の座敷飾りに銘木を用い、軒は垂木を扇に配るなど、瀟洒で開放的なつくりの離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009543"},{"id":"00009545","register_sub_id":"101","register_pk":"194338","name":"多田家住宅前ノ蔵","kana":"ただけじゅうたくまえのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県朝倉郡筑前町森山字耳取417-1","lat":33.45247957,"lng":130.62238074,"geo_status":"db","era":"明治3年","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"土蔵造平屋一部2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造平屋一部2階建","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0088","desc":"主屋西面に東西棟で建つ。土蔵造平屋一部二階建、桁行七・九メートル梁間五・一メートル、切妻造桟瓦葺で東面に戸口を設ける。外壁は漆喰塗で腰を海鼠壁とし、木瓜形に縁取りした小窓に銅扉を吊り、漆喰塗の小庇を付ける。主屋とともに重厚な表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009545"},{"id":"00009553","register_sub_id":"101","register_pk":"194346","name":"多田家住宅的場","kana":"ただけじゅうたくまとば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県朝倉郡筑前町森山字耳取417-1","lat":33.45276526,"lng":130.62306286,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積7.9㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0096","desc":"弓道場と相対し、西面して建つ。木造平屋建、桁行四メートル梁間二メートル、切妻造桟瓦葺。正面内法高に虹梁を架けて吹放しとし、残る三面は土壁とし、腰に杉皮を張る。虹梁上と隅柱には舟肘木を載せて桁を受ける。弓道場とともに屋敷景観に趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009553"},{"id":"00009554","register_sub_id":"101","register_pk":"194347","name":"多田家住宅物置","kana":"ただけじゅうたくものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県朝倉郡筑前町森山字耳取417-1","lat":33.45268326,"lng":130.62306412,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積6.6㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0097","desc":"的場の南側に、勝手門を挟んで建つ。木造平屋建、桁行三・四メートル梁間一・九メートル、切妻造桟瓦葺で、当地方で用いられた左桟瓦を葺く。平面は西正面を吹放しとし、他の三面を土壁とする。裏山で収集した薪や柴などを収めた、簡素なつくりの物置である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009554"},{"id":"00006659","register_sub_id":"101","register_pk":"107642","name":"箱嶋家住宅主屋","kana":"はこしまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県福岡市東区馬出2-662","lat":33.60817769,"lng":130.41816632,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積102㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"40 － 0056","desc":"旧唐津街道に東面する木造２階建の町家。桁行３間半梁間６間半の切妻造平入で、屋根は桟瓦葺とする。正面１階は中央に戸口を開き、両脇を出格子とする。２階は全面を出格子とする。内部は北側に通り土間、南に１列３室が並ぶ伝統的な町家平面である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006659"},{"id":"00010523","register_sub_id":"101","register_pk":"199463","name":"松村家住宅主屋","kana":"まつむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区大名2-127","lat":33.588357,"lng":130.39469,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積163㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"40 － 0115","desc":"もと福岡城の中堀であった敷地に所在する。設計は住宅改良会で、接客と居住を明瞭に区分し、水回りは渡廊下を介した別棟とする。床上の居室を広めて採光を考慮し、特に二階には広い縁を設ける。外観も出窓を多く設けて庇を重ね、軽やかで豊かな表情を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010523"},{"id":"00010525","register_sub_id":"101","register_pk":"199465","name":"松村家住宅土蔵","kana":"まつむらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区大名2-127","lat":33.588402,"lng":130.394601,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積12㎡","structure_material":"土蔵造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"40 － 0117","desc":"敷地の北西隅に位置し、南北棟で建つ二階建土蔵で、主屋の勝手口から坪庭を介した東面に出入口を設けて庇を付ける。小屋は登梁形式として内法を確保し、二階の収納の便を図る。床下換気口のグリル金物には星形の幾何学的装飾を飾り、近代的な趣を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010525"},{"id":"00010526","register_sub_id":"101","register_pk":"199466","name":"松村家住宅門及び塀","kana":"まつむらけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区大名2-127","lat":33.58826608,"lng":130.39481267,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"門 木造、瓦葺、間口2.0m、東方潜戸付 塀、コンクリートブロック造、瓦葺、総延長8.8m","structure_material":"門 木造","registered":"2015.03.26(平成27.03.26)","register_no":"40 － 0118","desc":"敷地の南辺を画する門と塀。門は棟門で西方に引違の格子戸と両開の板戸を持ち、東側に潜りの板戸を開く。門の左右に折曲がりで続く塀は煉瓦大のブロック積で、表面を洋館と同様にモルタル塗の粗面仕上げとする。通りの景観に寄与する、瀟洒な意匠の門塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010526"},{"id":"00010524","register_sub_id":"101","register_pk":"199464","name":"松村家住宅洋館","kana":"まつむらけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区大名2-127","lat":33.58827,"lng":130.394729,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"40 － 0116","desc":"通りに接して主屋の南に建つ応接用の洋館。寄棟造桟瓦葺で、各面に開口をとり、もとは西にパーゴラを附属していた。外壁はモルタル塗の粗面仕上げで、道路側は塀を連続させて街路景観を整える。接客空間を独立した洋間とする、和洋併設住宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010524"},{"id":"00009235","register_sub_id":"101","register_pk":"164788","name":"南久保田家住宅裏門","kana":"みなみくぼたけじゅうたくうらもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県うきは市吉井町福永字屋敷160-2","lat":33.35190477,"lng":130.76384377,"geo_status":"db","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"主屋の南西側、農業倉庫の東隣に東西棟で並び建ち、桁行5.2メートル梁間2.1メートル、木造平屋建、切妻造桟瓦葺である。南面東寄りに門を開き、両開き板戸を吊る。外壁は漆喰塗及び竪板張とする。小規模ながら堅実なつくりになる裏門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009235"},{"id":"00009229","register_sub_id":"101","register_pk":"164782","name":"南久保田家住宅米蔵","kana":"みなみくぼたけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県うきは市吉井町福永字屋敷160-2","lat":33.35219031,"lng":130.76367959,"geo_status":"db","era":"明治32年","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積69㎡","structure_material":"木造平屋一部2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地北西隅に南北棟で建ち、桁行9.9メートル梁間6.9メートル、木造平屋1部2階建、切妻造妻入、桟瓦葺である。布石積基礎上に建ち、外壁は真壁漆喰塗で、北面に下見板を張り、1階内部を土間とする。明治期の屋敷構えを伝える、建ちの高い米蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009229"},{"id":"00009234","register_sub_id":"101","register_pk":"164787","name":"南久保田家住宅材木置場及び脇門","kana":"みなみくぼたけじゅうたくざいもくおきばおよびわきもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県うきは市吉井町福永字屋敷160-2","lat":33.35190477,"lng":130.76421021,"geo_status":"db","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"主屋南東隅に5畳大の脇部屋を建て、その東側に脇門を開き、さらに矩折れに材木置場を延ばす。延長23.5メートル、木造、切妻造桟瓦葺である。材木置場は、表庭側を漆喰塗とし、裏側は吹放ちとして材木等を納める。屋敷の表構えと実用を兼ねた建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009234"},{"id":"00009228","register_sub_id":"101","register_pk":"164781","name":"南久保田家住宅主屋","kana":"みなみくぼたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県うきは市吉井町福永字屋敷160-2","lat":33.3521213,"lng":130.76401747,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積427㎡","structure_material":"木造平屋一部2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地中央に東面し、桁行24.6メートル梁間12.8メートルで、西に納戸、北に便所を張出す。木造平屋1部2階建、入母屋造桟瓦葺で、2階外壁は大壁で重厚な構えとする。18畳主室にスギ板の鏡天井を張るなど、長大材を用いた雄大なつくりになる大型民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009228"},{"id":"00009231","register_sub_id":"101","register_pk":"164784","name":"南久保田家住宅ツキアタリ蔵","kana":"みなみくぼたけじゅうたくつきあたりぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県うきは市吉井町福永字屋敷160-2","lat":33.35213796,"lng":130.76368197,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積56㎡","structure_material":"木造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"米蔵と農業倉庫の間に南北棟で建ち、桁行9.9メートル梁間4.9メートル、木造2階建、切妻造桟瓦葺で、出入口のある東面全長に下屋を付け、薪置場などに区画する。外壁は大壁漆喰塗で腰に竪板を張る。1階は土間で、2階を床板張とする、もと家財蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009231"},{"id":"00009233","register_sub_id":"101","register_pk":"164786","name":"南久保田家住宅農業倉庫","kana":"みなみくぼたけじゅうたくのうぎょうそうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県うきは市吉井町福永字屋敷160-2","lat":33.35195712,"lng":130.76370576,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積89㎡","structure_material":"木造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地南西隅に東西棟で建ち、桁行12.9メートル梁間6.9メートル、木造2階建、切妻造桟瓦葺で、南面1間通りを下屋として、屋敷外からの出入りの可能なつくりとする。外壁は竪板張とし、内部は納屋などに仕切る。農作との関連を示す大型倉庫である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009233"},{"id":"00009230","register_sub_id":"101","register_pk":"164783","name":"南久保田家住宅古蔵","kana":"みなみくぼたけじゅうたくふるぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県うきは市吉井町福永字屋敷160-2","lat":33.35219506,"lng":130.76375335,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積38㎡","structure_material":"木造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"米蔵の東側に東西棟で建ち、桁行7.8メートル梁間4.9メートル、木造2階建、切妻造桟瓦葺で、南面出入口に庇を付ける。外壁は大壁漆喰塗で軒裏まで塗込め、腰を竪板張とする。明治28年の家相図に確認される蔵で、往時の屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009230"},{"id":"00009232","register_sub_id":"101","register_pk":"164785","name":"南久保田家住宅味噌部屋","kana":"みなみくぼたけじゅうたくみそべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県うきは市吉井町福永字屋敷160-2","lat":33.35190239,"lng":130.76396274,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"主屋南側の水路脇に南北棟で建ち、桁行6.7メートル梁間4.0メートル、木造平屋建、切妻造妻入、桟瓦葺である。外壁は真壁漆喰塗で腰を竪板張とする。内部は土間で、主屋の土間に向く北面を出入口として庇を付ける。旧家の生活様態を伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009232"},{"id":"00012456","register_sub_id":"101","register_pk":"531780","name":"門司港涼山亭（旧丸山山荘）客間棟","kana":"もじこうりょうざんてい （きゅうまるやまさんそう）きゃくまとう","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県北九州市門司区丸山二丁目1363-15他","lat":33.93615,"lng":130.9688,"geo_status":"db","era":"昭和9年頃","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"40-151","desc":"敷地の谷側隅に建つ。渡廊下で主屋棟と接続し、道路沿いの一体的な屋敷構えを構成する。入母屋造桟瓦葺で座敷二室と茶室からなり、奥の座敷は遠方の眺望を確保するため道路側に張出して縁をつくる。都市近郊で営まれた接客施設の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012456"},{"id":"00012455","register_sub_id":"101","register_pk":"531779","name":"門司港涼山亭（旧丸山山荘）主屋棟","kana":"もじこうりょうざんてい （きゅうまるやまさんそう）しゅおくとう","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市門司区丸山二丁目1363-15他","lat":33.93623889,"lng":130.969,"geo_status":"db","era":"大正14年頃／昭和3年増築","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋及び2階建、瓦葺及びスレート葺、建築面積238㎡","structure_material":"木造平屋及び2階建","registered":"2018.05.10(平成30.05.10)","register_no":"40-150","desc":"門司港後背の山あいに建つ実業家の旧別宅。坂道の湾曲部に面した敷地の中央部に庭を設け、周囲に各建物を配する。主屋棟は庭側の座敷三室と道路側の水回りからなり、道路に沿って屋根が輻輳する複雑な外観を呈する。戦前の門司港の隆盛を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012455"},{"id":"00012457","register_sub_id":"101","register_pk":"531781","name":"門司港涼山亭（旧丸山山荘）離れノ間棟","kana":"もじこうりょうざんてい （きゅうまるやまさんそう）はなれまとう","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県北九州市門司区丸山二丁目1363-15他","lat":33.93604722,"lng":130.96895556,"geo_status":"db","era":"昭和3年頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"40-152","desc":"敷地の山側隅の高台に建つ。谷側入母屋造、山側寄棟造で、座敷と控えの二室からなる。敷地側に開口部を設け、庭を介して敷地を見渡す眺望を確保する。道路側は鉱滓煉瓦塀で閉じる。主屋棟、客間棟と同じく、都市近郊で営まれた接客施設の様相を伝えている","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012457"},{"id":"00015523","register_sub_id":"101","register_pk":"533538","name":"森田家住宅裏門及び南塀","kana":"もりたけじゅうたくうらもんおよびみなみべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県大川市大字小保字中ノ船津180","lat":33.20638611,"lng":130.37006389,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"裏門 煉瓦造、間口1.0m 南塀 煉瓦造、総延長9.0m","structure_material":"裏門 煉瓦造","registered":"2025.08.06(令和7.08.06)","register_no":"40 - 0244","desc":"仏間棟の南側に開く門と西に矩折に続き、敷地南西を区画する煉瓦塀。裏門の柱は煉瓦造で表面モルタル洗出仕上、頂部に半球状の装飾を付す。南塀は総延長9メートル、高さ1・7メートル、煉瓦造の塀で南面に控壁を付し、裏門とともに敷地南西の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015523"},{"id":"00015522","register_sub_id":"101","register_pk":"533537","name":"森田家住宅表門及び北塀","kana":"もりたけじゅうたくおもてもんおよびきたべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県大川市大字小保字中ノ船津180","lat":33.20648333,"lng":130.37015,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"表門 木造、瓦葺、間口2.0m 北塀 煉瓦造、瓦葺、総延長14m","structure_material":"表門 木造","registered":"2025.08.06(令和7.08.06)","register_no":"40 - 0243","desc":"通りに北面して建つ仏間棟用の薬医門と東西に続く煉瓦塀。表門は切妻造桟瓦葺で男梁上に立てた束と肘木で棟木を支持。軒は一軒疎垂木で門口に板戸を吊る。北塀は煉瓦造桟瓦葺でモルタル刷毛引仕上、軒蛇腹を廻らした重厚な外観で通りの歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015522"},{"id":"00015520","register_sub_id":"101","register_pk":"533535","name":"森田家住宅主屋","kana":"もりたけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県大川市大字小保字中ノ船津179-1他","lat":33.20638056,"lng":130.37018056,"geo_status":"db","era":"明治38年頃／昭和30年代・平成20年改修","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造2階建、瓦葺、建築面積210㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"40 - 0241","desc":"小保の町並みに位置し、仏壇製造用の漆及び金箔販売業の主屋。通りに北面する２階建入母屋造平入桟瓦葺で南西に角座敷を付す。正面一階は平格子構えとし、戸口上部に大戸を残す。角座敷は軸部や天井などを漆塗で丁寧に仕上げ、繊細な欄間彫刻など上質な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015520"},{"id":"00015521","register_sub_id":"101","register_pk":"533536","name":"森田家住宅仏間棟","kana":"もりたけじゅうたくぶつまとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県大川市大字小保字中ノ船津179-1他","lat":33.20643333,"lng":130.37007222,"geo_status":"db","era":"昭和2年頃／平成20年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"40 - 0242","desc":"主屋北側に接続する仏間棟。切妻造平入桟瓦葺で、北面東寄りに寄棟造の式台玄関を付し、南西に便所棟を附属する。内部は東に６畳の仏間、西に３畳の拝所を上段に設け、西端は仏壇を配し障子を建てる。軸部や天井などを漆塗で丁寧に仕上げた漆商らしい仏間棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015521"},{"id":"00014972","register_sub_id":"101","register_pk":"519232","name":"八名家住宅（旧庄野家住宅）主屋","kana":"やなけじゅうたく（きゅうしょうのけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市門司区柳町三丁目16-10他","lat":33.90338611,"lng":130.94018611,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積128㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"40 - 0218","desc":"門司駅東方に位置し、退役海軍少佐が建てた住宅。主屋は平屋建桟瓦葺で、平面は中廊下を南北に通して、東に洋室の応接室と床構え付き座敷、西に居間と台所を配した和洋折衷住宅。洋室の外壁は下見板張で内部は蛇腹付の漆喰天井に中心飾を備えた本格的なもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014972"},{"id":"00014973","register_sub_id":"101","register_pk":"519233","name":"八名家住宅（旧庄野家住宅）離れ","kana":"やなけじゅうたく（きゅうしょうのけじゅうたく）はなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市門司区柳町三丁目16-10他","lat":33.90338333,"lng":130.94031389,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"40 - 0219","desc":"主屋の東に南面して建つ離れ。平屋建入母屋造桟瓦葺の東西棟で四周に下屋を付し、西端で主屋と接続する。内部は２間続きの座敷で、東室を床構え付き座敷とし、南に縁を通す。床廻りは材料吟味し、繊細な組子を用いた欄間や付書院など洗練された離れ座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014973"},{"id":"00008601","register_sub_id":"101","register_pk":"134997","name":"吉住家住宅主屋","kana":"よしずみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県福岡市博多区上呉服町273","lat":33.59889001,"lng":130.41261066,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積108㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"40 － 0065","desc":"博多西門通りに北面する。間口五・五メートルの二階建。渡り廊下を介して台所棟を背面に付設。いずれも切妻造桟瓦葺。二階に座敷、一階に通り土間と仏間等を設ける。正面に庇を付け、二階に格子戸をたて、一階を全面ガラス戸とし、近代的な町家構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008601"},{"id":"00015265","register_sub_id":"101","register_pk":"530689","name":"吉村家住宅（旧大力家住宅）主屋","kana":"よしむらけじゅうたく（きゅうだいりきけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県うきは市浮羽町田篭字山口40-1他","lat":33.27365278,"lng":130.83166111,"geo_status":"db","era":"昭和前期／昭和38年増築、平成3年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、杉皮葺一部瓦葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"40 - 0230","desc":"隈上川西岸の集落に位置する旧農家の主屋。敷地東寄りに東面して建つ寄棟造茅葺で、杉皮を重ね葺き、周囲に桟瓦葺下屋を廻らす。内部は南に土間、北に田の字に部屋を並べ、北東を床構え付き座敷。杉皮を重ねた当地特有の茅葺屋根が集落の歴史的な景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015265"},{"id":"00013664","register_sub_id":"101","register_pk":"504610","name":"吉村家住宅井戸屋形","kana":"よしむらけじゅうたくいどやかた","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県福岡市中央区谷二丁目280","lat":33.57461667,"lng":130.38106111,"geo_status":"db","era":"大正14年頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積4.7㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"40 － 0180","desc":"便所・風呂棟の南に独立して建つ。平屋建で、四本の柱を内転びに立て、切妻造桟瓦葺の屋根を支持する。軸部材はすべて杉の丸太材である。井戸はコンクリート製の丸井戸とする。主屋や庭木と一体となって福岡城下の旧武家地に良好な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013664"},{"id":"00013661","register_sub_id":"101","register_pk":"504607","name":"吉村家住宅主屋","kana":"よしむらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県福岡市中央区谷二丁目280","lat":33.57478056,"lng":130.38096667,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積131㎡","structure_material":"木造平屋一部2階建","registered":"2021.02.04(令和3.02.04)","register_no":"40 － 0177","desc":"福岡城のもと武家地に所在。入母屋造桟瓦葺で四周に庇を廻し二重屋根にみせる。入母屋造の玄関から取次をはさんで主室の一〇畳座敷を配し東に四畳半、西に雁行して七畳半、台所をそれぞれ突出させる。屋根の取合いが複雑な、武家住宅の様相を現在に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013661"},{"id":"00013662","register_sub_id":"101","register_pk":"504608","name":"吉村家住宅旧納屋","kana":"よしむらけじゅうたくきゅうなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県福岡市中央区谷二丁目280","lat":33.57458889,"lng":130.38098333,"geo_status":"db","era":"明治中期／昭和20年頃・同25年頃改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"40 － 0178","desc":"敷地の南西隅に建つ。文政の建築と伝える旧主屋の付属建物との伝聞があり、敷地内で最も古い。平屋建切妻造桟瓦葺で真壁造竪板張とする。小作米の収納等に利用されたと思われるが、戦後に北に六畳、南に四畳半の二室に整備した。敷地の一角を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013662"},{"id":"00013663","register_sub_id":"101","register_pk":"504609","name":"吉村家住宅便所・風呂棟","kana":"よしむらけじゅうたくべんじょ・ふろとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県福岡市中央区谷二丁目280","lat":33.57465278,"lng":130.38105,"geo_status":"db","era":"大正14年頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"40 － 0179","desc":"敷地の南方に井戸屋形と並んで建つ。東西棟の平屋建入母屋造桟瓦葺。東半を便所、西半を脱衣所、浴室とし、西面を焚口として下屋を設ける。便所の開戸羽目板には老松や並び矢の透かしをいれるなど、小規模ながら洒脱な意匠をみせる。敷地の一角を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013663"},{"id":"00013897","register_sub_id":"101","register_pk":"507855","name":"料亭さとう別荘玄関棟","kana":"りょうていさとうべっそうげんかんとう","category":"住宅","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県小郡市小郡字下町1281-1","lat":33.39354722,"lng":130.54723889,"geo_status":"db","era":"大正14年／昭和中期・平成13年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"40 － 0189","desc":"英彦山に通じる街道に面する敷地に南面して建つ。入母屋造桟瓦葺で北西に洋間を張出しＬ字形平面とする。玄関の天井板の巧妙な配置や、洋間の虎、ライオン、人魚等をあしらった独特なレリーフなど、端正な外観を呈しながらも遊び心ある意匠を散りばめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013897"},{"id":"00013898","register_sub_id":"101","register_pk":"507856","name":"料亭さとう別荘広間棟","kana":"りょうていさとうべっそうひろまとう","category":"住宅","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県小郡市小郡字下町1281-1","lat":33.39364167,"lng":130.54731667,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"40 － 0190","desc":"玄関棟の東奥に接続する。木造平屋建、入母屋造で、八畳と一五畳を雁行形に配する。各室に銘木をあしらった床を構え、一五畳には付書院を設ける。庭側の柱を減らし、全体にガラス欄間障子を廻らすなど、庭との一体感を重視した上質なつくりの近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013898"},{"id":"00013899","register_sub_id":"101","register_pk":"507857","name":"料亭さとう別荘門","kana":"りょうていさとうべっそうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県小郡市小郡字下町1281-1","lat":33.39337778,"lng":130.54729167,"geo_status":"db","era":"明治後期／昭和2年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口3.3m","structure_material":"木造","registered":"2021.06.24(令和3.06.24)","register_no":"40 － 0191","desc":"市中央部を東西に貫き、英彦山に通じる街道に面して建つ。切妻造桟瓦葺の表門。本柱にせいの高い冠木を載せ腕木に繰型を付け桁を受ける。本柱、冠木ともに木太く、棟高も高い。豪壮な屋敷構えに相応しい雄渾なるつくりで、歴史的な街道の景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013899"},{"id":"00015264","register_sub_id":"101","register_pk":"530688","name":"冷泉荘（旧八木アパート）","kana":"れいぜんそう（きゅうやぎあぱーと）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福岡県","address":"福岡県福岡市博多区上川端町130-1他","lat":33.59378889,"lng":130.40843056,"geo_status":"db","era":"昭和33年／平成23年改修","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄筋コンクリート造地上5階地下1階建、建築面積211㎡、塔屋付","structure_material":"鉄筋コンクリート造地上5階地下1階建","registered":"2024.12.03(令和6.12.03)","register_no":"40 - 0229","desc":"櫛田神社北西に位置する集合住宅。路地に北面する鉄筋コンクリート造地上５階地下１階建で外壁モルタル刷毛引仕上。階段室を挟んで住戸を配し上層階はセットバックし、テラスとする。一階南東は旧共同浴場。旧博多部に残る戦後復興期の貴重な民間集合住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015264"},{"id":"00007700","register_sub_id":"101","register_pk":"108682","name":"池田家住宅石垣","kana":"いけだけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県嬉野市塩田町大字五町田字辺田乙4345","lat":33.12617411,"lng":130.02978818,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"石造、総延長65m","structure_material":"石造","registered":"2009.04.28(平成21.04.28)","register_no":"41 － 0075","desc":"屋敷地の南面から東面にかけて築かれ、山裾に占める土地の段差を調整するとともに、主屋座敷前庭を画する。総延長６５ｍで、緑色を帯びた地元産の塩田石が用いられ、前庭側は整形の塩田石を切込み矧ぎ積とする。篠岳裾野の広がる集落の景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007700"},{"id":"00007699","register_sub_id":"101","register_pk":"108681","name":"池田家住宅座蔵","kana":"いけだけじゅうたくざぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県嬉野市塩田町大字五町田字辺田乙4345","lat":33.12607117,"lng":130.02971917,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"41 － 0074","desc":"主屋の東に南北棟で建つ。南入母屋北切妻造の桟瓦葺で、南面に庇を付ける。桁行１０ｍ梁間４．９ｍの土蔵造２階建。１階は南北に３室の倉庫を並べ、２階は南端に座敷を配する。座敷はトコなどを構え、真壁造とし二方に縁をまわす。良質な意匠をもつ座蔵の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007699"},{"id":"00007698","register_sub_id":"101","register_pk":"108680","name":"池田家住宅主屋","kana":"いけだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県嬉野市塩田町大字五町田字辺田乙4345","lat":33.12601533,"lng":130.02961466,"geo_status":"db","era":"江戸末期／大正後期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積267㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"41 － 0073","desc":"敷地中央に南面して建つ。寄棟造桟瓦葺で、庇をまわし、上屋壁面を漆喰で塗り込める。正面中央に入母屋造の式台玄関を付け、西に仏間、背面に釜屋を付設。内部は東端に土間、西に六間取の床上部を配し、前列西端を主座敷とする。在郷における住宅の変遷を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007698"},{"id":"00002321","register_sub_id":"101","register_pk":"103311","name":"牛津町会館（旧田中丸家住宅）","kana":"うしづちょうかいかん（きゅうたなかまるけじゅうたく）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県小城市牛津町牛津586-1","lat":33.24738383,"lng":130.20427228,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、瓦葺、建築面積410㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"41 － 0025","desc":"九州の財界人として著名な田中丸善蔵の本宅として建設された。中央の玄関棟を挟んで南に座敷棟，北に居室棟を配し，平面にあわせて複雑な屋根を架ける。豪壮な外観に対し，内部は繊細な木割の数寄屋風の意匠にまとめられる。近代の牛津を代表する建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002321"},{"id":"00012662","register_sub_id":"101","register_pk":"367956","name":"香月家住宅主屋","kana":"かつきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県嬉野市塩田町大字久間字西山乙3595-1他","lat":33.151592,"lng":130.059204,"geo_status":"geocoded","era":"明治前期／昭和20年頃・同40年頃・平成8年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋一部2階建、瓦葺、建築面積202㎡","structure_material":"木造平屋一部2階建","registered":"2018.11.02(平成30.11.02)","register_no":"41 － 0110","desc":"志田焼産地の西山にある窯元宅。主屋は敷地正面の路地に南面して建つ。軒の出の短い入母屋造妻入の二階建で両側に大きな袖下屋を付し、正面に下屋を通す。内部は東に土間、西に2列4室を配し、西列奥に座敷を設ける。九州北部に分布する町家と同形式の民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012662"},{"id":"00009081","register_sub_id":"101","register_pk":"162441","name":"木下家住宅主屋","kana":"きのしたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県多久市東多久町大字別府4650-1他","lat":33.28311875,"lng":130.14136087,"geo_status":"db","era":"明治22年／昭和3年増築","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造2階建、瓦葺、建築面積284㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"41 － 0080","desc":"通りの南に占める敷地の西北隅に位置する。東西棟の寄棟造桟瓦葺、木造二階建、間口２５ｍ奥行１３ｍ。東半部を広い土間、西半部を床上部とする。十二畳の主座敷にはトコや棚、付書院を構える。近代における大型の商家建築の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009081"},{"id":"00009083","register_sub_id":"101","register_pk":"162443","name":"木下家住宅つなぎ屋","kana":"きのしたけじゅうたくつなぎや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県多久市東多久町大字別府4650-1他","lat":33.28292417,"lng":130.14128896,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"41 － 0082","desc":"主屋の南面西寄りに接して建つ。桁行９．０ｍ梁間３．３ｍの木造平屋建、南北棟の切妻造桟瓦葺。東寄りに廊下を通し、西側には北から数室に間仕切り、中央に浴室、南寄りに便所が配される。浴室の天井や廊下の円窓など大正期の雰囲気を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009083"},{"id":"00009082","register_sub_id":"101","register_pk":"162442","name":"木下家住宅離れ","kana":"きのしたけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県多久市東多久町大字別府4650-1他","lat":33.28281418,"lng":130.14130165,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"41 － 0081","desc":"つなぎ屋の南に東西棟で建つ。桁行８．３ｍ梁間４．９ｍの木造平屋建、入母屋造桟瓦葺で、下屋を廻らす。八畳の主座敷と六畳の次の間を東西に並べ、北・東に榑縁をまわす。北の庭園側にガラス戸をたてて開放的に扱い、軽快な外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009082"},{"id":"00014979","register_sub_id":"101","register_pk":"519239","name":"旧松野家住宅(野口家住宅)主屋","kana":"きゅうまつのけじゅうたく（のぐちけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県佐賀市大和町大字梅野字水無3068","lat":33.35926667,"lng":130.28245,"geo_status":"db","era":"明治42年頃","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積205㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"41 - 0131","desc":"佐賀市街地北方の山間集落に位置する旧家の主屋。木造二階建桟瓦葺で、入母屋造の屋根を直交し、全体に矩折れの平面とする。東に広い土間、西に二列三室を配し、上手正面に主座敷を突出する。式台や拭漆塗仕上とした仏間など、随所に家格を示す設えを備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014979"},{"id":"00014980","register_sub_id":"101","register_pk":"519240","name":"旧松野家住宅(野口家住宅)小屋","kana":"きゅうまつのけじゅうたく(のぐちけじゅうたく)こや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県佐賀市大和町大字梅野字水無3068","lat":33.35925556,"lng":130.282625,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積61㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"41 - 0132","desc":"主屋の東、敷地北東隅に西面して建ち、座敷と物置からなる建物。木造つし二階建桟瓦葺。二階外壁は妻壁を大壁とする。物置には農機具や薪等を納めた。座敷は床、天袋、平書院を備え、縁を廻らす。青年組の宿にも利用するなど当地域の習俗を示す上でも貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014980"},{"id":"00014982","register_sub_id":"101","register_pk":"519242","name":"旧松野家住宅(野口家住宅)取水池","kana":"きゅうまつのけじゅうたく(のぐちけじゅうたく)しゅすいいけ","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県佐賀市大和町大字梅野字水無3068","lat":33.35913333,"lng":130.28259167,"geo_status":"db","era":"大正前期／昭和40年頃改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"石造、面積26㎡","structure_material":"石造","registered":"2024.03.06(令和6.03.06)","register_no":"41 - 0134","desc":"敷地東辺石塀北端に設けた取水地。石垣沿いの水路から取水する。石垣と同様の花崗岩を用いた石垣を、北に開いたコの字形に積上げ池を囲む。池はほぼ正方形で、中央にコンクリート製の橋を渡す。石垣との取合や端部の納まりなどに、石材加工技術の高さを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014982"},{"id":"00014981","register_sub_id":"101","register_pk":"519241","name":"旧松野家住宅(野口家住宅)門柱及び石垣","kana":"きゅうまつのけじゅうたく(のぐちけじゅうたく)もんちゅうおよびいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県佐賀市大和町大字梅野字水無3068","lat":33.35896667,"lng":130.2825,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"門柱 石造、間口2.8m 石垣 石造、総延長55m","structure_material":"門柱 石造","registered":"2024.03.06(令和6.03.06)","register_no":"41 - 0133","desc":"敷地南東隅に門柱一対を立て、左右に石垣を延ばし、敷地南半を取り囲む。いずれも同質の花崗岩を使用し、石柱は角を江戸切仕上、頂部を角錐形とする。石垣は全体を反上げて積上げ、出隅部を鎬積とし、敷地形状に合わせて天端を揃えるなど高い技術を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014981"},{"id":"00011595","register_sub_id":"101","register_pk":"210516","name":"旧百﨑家住宅主屋","kana":"きゅうももさきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県佐賀市水ケ江三丁目231","lat":33.24387194,"lng":130.30801889,"geo_status":"db","era":"明治前期／昭和6年増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋一部2階建、茅葺及び瓦葺、建築面積245㎡","structure_material":"木造平屋一部2階建","registered":"2017.05.02(平成29.05.02)","register_no":"41-0098","desc":"佐賀城下旧武家地に位置する。主屋は茅葺寄棟造で、棟を三方に鉤の手状に折り曲げた複雑な外観を持ち、四方に桟瓦葺の下屋を廻らし、立ちの低い造りとする。座敷は庭園に向けて開放的な造りで、内部造作も質が高い。佐賀城下の往時の景観を今に伝える大規模住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011595"},{"id":"00002713","register_sub_id":"101","register_pk":"103703","name":"小柳酒造離れ","kana":"こやなぎしゅぞうはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県小城市小城町904-1","lat":33.29883514,"lng":130.20297537,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積130㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0028","desc":"主屋の北方に位置し，西南端が主屋角屋状部北東端に接続する。東西棟，桟瓦葺，入母屋造の平屋建で，４畳半と床の間をもつ６畳の２室から成り，南北両面に縁廊下を付ける。買足した隣地に在り，小柳酒造発展の様子を物語る建造物になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002713"},{"id":"00014435","register_sub_id":"101","register_pk":"511424","name":"庄野家住宅隠居所","kana":"しょうのけじゅうたくいんきょじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県佐賀市本庄町大字本庄字一本黒木七角5他","lat":33.23941944,"lng":130.29678611,"geo_status":"db","era":"昭和前期／昭和45年移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"41 - 0129","desc":"水路に囲まれた敷地の北、金蔵の西に建つ隠居所。入母屋造桟瓦葺、四周に庇を廻らす。東に床棚付の座敷八畳と次の間六畳を東西に並べ、南北に縁を付しガラス戸を建て込む。部屋縁境の額入障子や欄間、付書院障子に用いた精緻な組子が目を引く近代和風の書院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014435"},{"id":"00014434","register_sub_id":"101","register_pk":"511423","name":"庄野家住宅金蔵（旧佐賀城本丸御蔵）","kana":"しょうのけじゅうたくかねぐら（きゅうさがじょうほんまるおくら）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県佐賀市本庄町大字本庄字一本黒木七角5他","lat":33.23938611,"lng":130.29691111,"geo_status":"db","era":"江戸末期／明治前期・昭和45年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"41 - 0128","desc":"佐賀城南西、国道に南面した敷地東に建つ佐賀城の蔵を移築した土蔵。土蔵造二階建南北棟の本瓦葺で、一階北面に下屋を付し西面北寄りに庇付の出入口を設ける。外周部は腰高の竪板張とし上部は漆喰塗で軒裏は曲線状の揚塗とする。佐賀城の遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014434"},{"id":"00011601","register_sub_id":"101","register_pk":"210522","name":"中野家住宅石垣","kana":"なかのけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県藤津郡太良町大字伊福字椎木坂甲1978","lat":33.04089,"lng":130.16248611,"geo_status":"db","era":"明治42年頃","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"石造、総延長97m","structure_material":"石造","registered":"2017.05.02(平成29.05.02)","register_no":"41-0104","desc":"門柱の東側に北へ矩折れに延びる三〇メートルと門柱の西側から庭園を囲うように延びる六七メートルの石垣。切石を二段積み、塀を載せるため上端は平坦とする。丁寧な造りで保存状態も良く、往時の屋敷構えを知る上で欠かすことができない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011601"},{"id":"00011598","register_sub_id":"101","register_pk":"210519","name":"中野家住宅上の取水口","kana":"なかのけじゅうたくかみのしゅすいこう","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県藤津郡太良町大字伊福字椎木坂甲1978","lat":33.04123889,"lng":130.16222194,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造、幅2.4m、高さ1.7m","structure_material":"煉瓦造","registered":"2017.05.02(平成29.05.02)","register_no":"41-0101","desc":"敷地北面の崖に山から浸透する水を溜める煉瓦造の貯水槽。水槽の北側にあり、槽径約三メートル、深さ約六メートルで、取水口は幅二・四メートル、高さ一・七メートルのアーチ門を開く。貯水槽として最も規模が大きく、豊富な水量で敷地内の給水を担った。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011598"},{"id":"00011599","register_sub_id":"101","register_pk":"210520","name":"中野家住宅下の取水口","kana":"なかのけじゅうたくしものしゅすいこう","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県藤津郡太良町大字伊福字椎木坂甲1978","lat":33.04134889,"lng":130.16261611,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造、幅2.5m、高さ2.3m","structure_material":"煉瓦造","registered":"2017.05.02(平成29.05.02)","register_no":"41-0102","desc":"敷地北面の崖の東側にある煉瓦造の貯水槽。槽径は約一・五メートルで、取水口は幅一・五メートル、高さ二・二メートルのアーチ門を開く。上の取水口より規模が小さいものの、技法や意匠は共通しており、保存状態も良い。敷地内の給水設備の様相を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011599"},{"id":"00011596","register_sub_id":"101","register_pk":"210517","name":"中野家住宅主屋","kana":"なかのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県藤津郡太良町大字伊福字椎木坂甲1978","lat":33.04108611,"lng":130.16243,"geo_status":"db","era":"明治42年／大正期増築","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積462㎡","structure_material":"木造2階一部平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"41-0099","desc":"主屋棟、座敷棟、納戸棟を一間幅の廊下で結ぶ。主屋棟は虹梁や蟇股など意匠を凝らした式台玄関を持ち、座敷棟に椅子座に合わせてトコを腰高に設けた座敷と伝統的な座敷の両者を配す。接客や教育活動の使用のため工夫された平面構成に、近代的展開を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011596"},{"id":"00011597","register_sub_id":"101","register_pk":"210518","name":"中野家住宅水槽","kana":"なかのけじゅうたくすいそう","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県藤津郡太良町大字伊福字椎木坂甲1978","lat":33.04121,"lng":130.16222194,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦造、面積3.3㎡","structure_material":"煉瓦造","registered":"2017.05.02(平成29.05.02)","register_no":"41-0100","desc":"敷地の北西にある水槽。煉瓦造で幅一・五メートル、奥行二・二メートル、高さ二・〇メートル。上層は深さ一・〇メートルの水槽で、下層は東正面にアーチを開く。上の取水口から汲み上げた水を水圧を利用して各建物へ給水する近代的な自家用給水施設の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011597"},{"id":"00011600","register_sub_id":"101","register_pk":"210521","name":"中野家住宅門柱","kana":"なかのけじゅうたくもんちゅう","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県藤津郡太良町大字伊福字椎木坂甲1978","lat":33.041035,"lng":130.16255111,"geo_status":"db","era":"明治42年頃","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"石造、間口3.8m","structure_material":"石造","registered":"2017.05.02(平成29.05.02)","register_no":"41-0103","desc":"主屋の式台玄関の南方に開く門。間口三・八メートルで、石柱二本を立てる。石柱は凝灰岩で一辺四四センチメートルの方形で、高さ三・一メートル。隅を几帳面取し、頂部には切石を一段と、蛇腹の装飾を持つ笠石を載せ、重厚な表構えをかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011600"},{"id":"00002186","register_sub_id":"101","register_pk":"103176","name":"深川家住宅主屋","kana":"ふかがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県小城市小城町877-2","lat":33.30042538,"lng":130.20431666,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積167㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"41 － 0017","desc":"旧小城城下と鎮守である祇園神社を結ぶ街道沿いにほぼ西面して建つ。間口６間規模，正面を入母屋造，背面を切妻造とした妻入の町家で，北側をカミテとして帳場，仏間，座敷を配する。改造はみられるものの，造り酒屋の店舗の様相を今に伝えていることで貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002186"},{"id":"00002187","register_sub_id":"101","register_pk":"103177","name":"深川家住宅土蔵","kana":"ふかがわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県小城市小城町877-2","lat":33.30037455,"lng":130.20447918,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積66㎡","structure_material":"土蔵造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"41 － 0018","desc":"主屋の東方に位置する東西棟，切妻造，桟瓦葺の２階建土蔵。桁行５間，梁行２間半規模で，住居に供したため改造は受けているが，もと平屋建で，内部を大きく２室に分け，西面と南面に戸前を設ける。造り酒屋施設の欠くことのできない構成要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002187"},{"id":"00002318","register_sub_id":"101","register_pk":"103308","name":"前田家住宅北の蔵","kana":"まえだけじゅうたくきたのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県伊万里市立花町字ロノ町4028","lat":33.2738689,"lng":129.882278,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、瓦葺、建築面積61㎡","structure_material":"土蔵造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"41 － 0022","desc":"屋敷の北辺を区切る位置に建つ土蔵。２階建，切妻造，瓦葺で，南面屋敷側に下屋を付け蔵前とする。主屋裏庭の後方に物置として建設されたもので，下屋の東半にも簡易な仕切を設け，この部分も作業用具の収納場所とする。簡素だが，丁寧で堅牢な造りである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002318"},{"id":"00002315","register_sub_id":"101","register_pk":"103305","name":"前田家住宅主屋","kana":"まえだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県伊万里市立花町字ロノ町4028","lat":33.27355759,"lng":129.88216883,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積291㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"41 － 0019","desc":"伊万里郷の大庄屋を務めた家の屋敷で，主屋は南北に長い敷地のほぼ中央に建つ。広い土間をもつ主体部の東に座敷部を接続した複雑な平面になり，主体部の茅葺屋根は鉤形に棟を配る。佐賀県の民家を特徴づける「くど造」の最も発達した姿を伝える遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002315"},{"id":"00002320","register_sub_id":"101","register_pk":"103310","name":"前田家住宅水車小屋","kana":"まえだけじゅうたくすいしゃごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"佐賀県","address":"佐賀県伊万里市立花町字ロノ町4028","lat":33.27387445,"lng":129.882111,"geo_status":"db","era":"江戸後期／明治後期改造","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"41 － 0024","desc":"西の蔵の北に接続して西側街路に面して建つ。棟を南北に通す桁行の長い建物で，南端部を２階建とし階下を裏庭に通じる２階建の門口とする。水車施設は失われ，門部分は改造されているが，軸部，外観等はよく残り，大規模民家の生活施設を知る上で貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002320"},{"id":"00002319","register_sub_id":"101","register_pk":"103309","name":"前田家住宅薪小屋","kana":"まえだけじゅうたくたきぎごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県伊万里市立花町字ロノ町4028","lat":33.273876,"lng":129.882172,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"41 － 0023","desc":"平屋建，切妻造，桟瓦葺の小規模な建物で，北の蔵の西に接して建つ。住居として内部は改造されているが軸部や外観は旧状を残す。敷地北辺を区切る位置にあり，薪その他を収納する施設として，北の蔵，水車小屋とともに主屋裏庭の作業空間を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002319"},{"id":"00002317","register_sub_id":"101","register_pk":"103307","name":"前田家住宅西の蔵","kana":"まえだけじゅうたくにしのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県伊万里市立花町字ロノ町4028","lat":33.27370259,"lng":129.88209817,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、瓦葺、建築面積139㎡","structure_material":"土蔵造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"41 － 0021","desc":"主屋の土間の北に接続して建ち，西面を街路に面する。２階建，切妻造，瓦葺で，屋敷側の東面に下屋を付け広い蔵前をつくる。当家においては最大の土蔵で，茅葺の主屋と一体となって独特の外観を形成し，屋敷の西面を構成する重要な要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002317"},{"id":"00002316","register_sub_id":"101","register_pk":"103306","name":"前田家住宅東の蔵","kana":"まえだけじゅうたくひがしのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県伊万里市立花町字ロノ町4028","lat":33.27357738,"lng":129.88233596,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積51㎡","structure_material":"土蔵造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"41 － 0020","desc":"主屋座敷部東端の上段の間の北に続いて建つ土蔵。２階建，切妻造，瓦葺で，南側の上段の間に続く位置とともに，東面にも２ヶ所の戸口を開ける。座敷蔵の性格をもち，主屋を中心とした複雑で変化に富んだ建築構成の主要な要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002316"},{"id":"00012071","register_sub_id":"101","register_pk":"211012","name":"水野旅館観風亭","kana":"みずのりょかんかんぷうてい","category":"住宅","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県唐津市東城内96-1","lat":33.45428,"lng":129.975584,"geo_status":"db","era":"昭和13年／昭和46年頃・同50年代改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積156㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"41-107","desc":"唐津湾を臨む海岸沿いに建つ。玄関棟と座敷棟からなり、入母屋造の屋根を直交させ、複雑な外観をつくる。玄関棟は式台の奥に板敷の間を設け、座敷棟は中二階として、広縁の開放的な窓から海を望む趣向が凝らされている。端正な座敷飾りを備えた良質なもと別荘。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012071"},{"id":"00012072","register_sub_id":"101","register_pk":"211013","name":"水野旅館門","kana":"みずのりょかんもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県唐津市東城内96-1","lat":33.45416,"lng":129.975493,"geo_status":"db","era":"江戸末期／昭和48年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.0m、西方袖塀・東方脇戸付","structure_material":"木造","registered":"2017.10.27(平成29.10.27)","register_no":"41-108","desc":"敷地南面を画す表門。切妻造本瓦葺の一間薬医門で、両脇に袖塀を付け、東側に潜戸を開く。本柱は五平で、控柱間を繋ぐ梁は曲材を用い、三筋架けて桁を受け、棟木は冠木に束を立て、舟肘木で受ける。本柱、控柱、冠木など木柄が大きく堂々たる風格を備えた門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012072"},{"id":"00005670","register_sub_id":"101","register_pk":"106658","name":"矢野酒造離れ","kana":"やのしゅぞうはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市大字高津原字一本杉3903-1他","lat":33.113106,"lng":130.093552,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、瓦葺、建築面積98㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0054","desc":"主屋の西奥に渡り廊下を介して接続する接客用の東西棟。木造２階建で，入母屋造，桟瓦葺，外壁は竪羽目板張である。東面と南面に瓦葺庇がつく。内部は床構えを持つ１５畳座敷と次の間１０畳からなり，東，南，西の３面に縁を巡らす。２階も１階と同平面である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005670"},{"id":"00010074","register_sub_id":"101","register_pk":"196221","name":"旅館綿屋本館","kana":"りょかんわたやほんかん","category":"住宅","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県唐津市大名小路150他","lat":33.45045765,"lng":129.97280799,"geo_status":"db","era":"明治後期／昭和前期・昭和55改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階一部3階建、瓦葺、建築面積401㎡","structure_material":"木造2階一部3階建","registered":"2014.04.25(平成26.04.25)","register_no":"41 － 0095","desc":"松浦川と唐津大名小路に挟まれた敷地に建つ。入母屋造で庇を廻らす車寄は、亀甲状の天井を張り、二軒の垂木を千鳥に配る。客室の銘木による座敷飾や透彫欄間、各種建具などの意匠も洗練されている。もと炭鉱主の別荘という由緒をもつ、大規模で上質な木造旅館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010074"},{"id":"00010075","register_sub_id":"101","register_pk":"196222","name":"旅館綿屋洋館","kana":"りょかんわたやようかん","category":"住宅","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県唐津市大名小路153","lat":33.45038417,"lng":129.97265051,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"41 － 0096","desc":"本館の南西隅に接続する。御影石の布基礎の上に建ち、本館の玄関に向く北面に二重扉の出入口を開く。天井をモールディングで折上げ、木製の中心飾を付ける。当初は本館から独立して建てられた洋風意匠の応接間で、明治期の、洋館を並立した別邸建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010075"},{"id":"00007421","register_sub_id":"101","register_pk":"108403","name":"鮎川家住宅石垣及び石段","kana":"あゆかわけじゅうたくいしがきおよびいしだん","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県平戸市田平町山内免字水無742","lat":33.3693492,"lng":129.58260074,"geo_status":"db","era":"昭和14頃","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"石垣 石造、延長218m 北石段 石造25段、幅1.7m 南石段 石造14段、幅1.5m","structure_material":"石垣 石造","registered":"2008.10.23(平成20.10.23)","register_no":"42 － 0084","desc":"屋敷地の南面は２段に石垣が築かれる。石垣は谷積とし、上が延長８４ｍで高さ０．２～３．２ｍ、下が延長１０４ｍで高さは０．３～１．３ｍ。石段側壁は延長３０ｍで、布積や亀甲積とし、意匠に変化を与える。谷間に落ち着きのある外構を構築する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007421"},{"id":"00007420","register_sub_id":"101","register_pk":"108402","name":"鮎川家住宅主屋","kana":"あゆかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県平戸市田平町山内免字水無742","lat":33.369141,"lng":129.582016,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積317㎡","structure_material":"木造2階一部平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"42 － 0083","desc":"日の浦港から北に入った谷間に所在する。東西棟の入母屋造木造２階建を中心に、東に寄棟造平屋建、西に切妻造、南北に下屋を付ける。南面に内玄関と玄関を設け、座敷飾りを備える主座敷を東南隅に配する。繊細な意匠をもつ近代和風住宅の一例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007420"},{"id":"00001021","register_sub_id":"101","register_pk":"102011","name":"池上家住宅","kana":"いけがみけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県長崎市大浦町23-10","lat":32.73628999,"lng":129.87226866,"geo_status":"db","era":"明治20代末","year":1887,"year_source":"converted","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造２階建，瓦葺，建築面積95㎡","structure_material":"木造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"42 － 0009","desc":"当初英国の貿易商の住宅として建築されたと伝える，下見板張の洋風建築。平面は中央に廊下と階段のある玄関部を置き左右に対称形に居室を配する型式になる。２階は前面にベランダを設けるなど標準的な明治中期の洋風住宅で，長崎らしさを伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001021"},{"id":"00004679","register_sub_id":"101","register_pk":"105669","name":"内野家住宅石段","kana":"うちのけじゅうたくいしだん","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長崎県","address":"長崎県平戸市岩の上町1165-1","lat":33.36230648,"lng":129.55607672,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石造、面積13㎡","structure_material":"石造","registered":"2005.02.09(平成17.02.09)","register_no":"42 － 0043","desc":"門柱前から南北道路に至る幅員３．６ｍ，長さ３．６ｍ，１０段の直線石段。中央部は幅３３ｃｍ，厚１５ｃｍ，長１３０ｃｍ程度の砂岩の切石を２～３個並べ，両端に自然石を置く構成をとる。両側の石垣や塀，生垣とともに平戸の武家屋敷の面影を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004679"},{"id":"00004676","register_sub_id":"101","register_pk":"105666","name":"内野家住宅主屋","kana":"うちのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県平戸市岩の上町1165-1","lat":33.36231759,"lng":129.55596669,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積192㎡","structure_material":"木造平屋一部2階建","registered":"2005.02.09(平成17.02.09)","register_no":"42 － 0040","desc":"平戸旧城下の武家屋敷地に位置し，南北道路の西側敷地に東面して建つ。入母屋造玄関の南方に２階建の居住部，北方にＬ字形に平屋建の座敷部を配した寄棟造，桟瓦葺で，棟札から「大工棟梁米原音之助」が判明。武家屋敷の流れを継承した近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004676"},{"id":"00004678","register_sub_id":"101","register_pk":"105668","name":"内野家住宅門及び塀","kana":"うちのけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県平戸市岩の上町1165-1","lat":33.36232339,"lng":129.55607097,"geo_status":"db","era":"江戸後期／大正15頃改造","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"門 コンクリート造、間口2.3m、塀 石造及び土塀、瓦葺、延長43m","structure_material":"門 コンクリート造","registered":"2005.02.09(平成17.02.09)","register_no":"42 － 0042","desc":"主屋玄関前に位置する門柱は間口２．３ｍ，高さ１．６ｍで，柱頭部付近に丸を４つ縦に並べた飾りを３面に付ける。塀は南北道路沿いの石垣上に築かれ，下部石積，上部白漆喰塗土塀とし，桟瓦葺の小屋根を載せる。門前の石段とともに武家屋敷の表構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004678"},{"id":"00004677","register_sub_id":"101","register_pk":"105667","name":"内野家住宅煉瓦塀","kana":"うちのけじゅうたくれんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県平戸市岩の上町1165-1","lat":33.36238704,"lng":129.55604588,"geo_status":"db","era":"大正15頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"煉瓦造、延長18m","structure_material":"煉瓦造","registered":"2005.02.09(平成17.02.09)","register_no":"42 － 0041","desc":"主屋座敷部東側の築庭をコ字型に囲い，玄関側に庭門を開く。高さ１．５ｍ程，折れ曲がり延長約１８ｍ規模で，鉱滓煉瓦を半枚厚で積む。要所に煉瓦１枚厚の柱を配し，頂部も煉瓦で屋根形を形づくるなど丁寧なつくりとし，茶室前の箱庭的空間演出の背景をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004677"},{"id":"00007416","register_sub_id":"101","register_pk":"108398","name":"鵜殿家住宅旧主屋","kana":"うどのけじゅうたくきゅうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県島原市上の町868-1","lat":32.789482,"lng":130.369339,"geo_status":"db","era":"天保13","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積216㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"42 － 0079","desc":"島原城の東方、通りに西面する平入町家。トコを構える座敷など３室を逆Ｌ字型に配する座敷部と、その南に建つ土間・居室部のつし２階建からなる。屋根桟瓦葺で、部分的に漆喰で塗り固める。外壁は漆喰仕上げの大壁造で腰下見板張。城下町の町並み景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007416"},{"id":"00007417","register_sub_id":"101","register_pk":"108399","name":"鵜殿家住宅主屋","kana":"うどのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県島原市上の町868-1","lat":32.78937745,"lng":130.3693478,"geo_status":"db","era":"大正期／昭和60頃改修","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積67㎡","structure_material":"木造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"42 － 0080","desc":"旧主屋の南に接して建つ平入町家。正面８．４ｍ奥行７．９ｍの木造２階建で、１階北端に幅１．４ｍの通路を設ける。屋根は、旧主屋より棟を少し高くする切妻造桟瓦葺で、正面に深い下屋を付ける。旧主屋と一体となり、伝統的な街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007417"},{"id":"00002728","register_sub_id":"101","register_pk":"103718","name":"梅ヶ枝酒造住居","kana":"うめがえしゅぞうじゅうきょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長崎県","address":"長崎県佐世保市城間町317","lat":33.08995236,"lng":129.81507146,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"42 － 0013","desc":"主屋の東北方に位置する。東西棟，片寄棟造，桟瓦葺，木造平屋建で，桁行１１ｍ，梁間６．３ｍの規模。床の間・棚をもつ８畳，６畳２室の３室構成で，南・東面に縁を廻す。縁の外側にはさらに土庇を付けるなど，南東方に庭を臨む「離れ」風のつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002728"},{"id":"00005210","register_sub_id":"101","register_pk":"106200","name":"梅ヶ谷津稲荷社","kana":"うめがやついなりしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長崎県","address":"長崎県平戸市明の川内町348","lat":33.34958941,"lng":129.54484086,"geo_status":"db","era":"天保4","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"石造、高さ1.0m、石造鳥居付","structure_material":"石造","registered":"2005.12.26(平成17.12.26)","register_no":"42 － 0049","desc":"敷地の南西に位置する。屋根の反りが強調された高さ１．０ｍの小規模な石造の祠と，間口１．３ｍ，高さ２．２ｍの石造の明神鳥居からなり，共に年紀が陰刻される。藩主松浦熈が定めた平戸島８８箇所の第４番札所として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005210"},{"id":"00005209","register_sub_id":"101","register_pk":"106199","name":"梅ヶ谷津偕楽園石垣","kana":"うめがやつかいらくえんいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県平戸市明の川内町348","lat":33.34988294,"lng":129.54517704,"geo_status":"db","era":"天保10","year":1839,"year_source":"db","year_min":1839,"year_max":1839,"year_label":null,"structure":"石造、延長97m","structure_material":"石造","registered":"2005.12.26(平成17.12.26)","register_no":"42 － 0048","desc":"主屋の南側に東西方向に築かれた５５ｍの石垣と，その西側端部から南方向へ弓状にのびる４２ｍの石垣からなる。東西の石垣は，たるみをつけた小型石の空積部分と巨石積部分からなり，畑地を区切る南北の石垣は５ｍ高の乱積とする。庭園の主要な構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005209"},{"id":"00005208","register_sub_id":"101","register_pk":"106198","name":"梅ヶ谷津偕楽園石塀及び石段","kana":"うめがやつかいらくえんいしべいおよびいしだん","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県平戸市明の川内町348","lat":33.34996085,"lng":129.54524262,"geo_status":"db","era":"天保10","year":1839,"year_source":"db","year_min":1839,"year_max":1839,"year_label":null,"structure":"石塀 石造、延長6.0m、石段 石造、延長11m","structure_material":"石塀 石造","registered":"2005.12.26(平成17.12.26)","register_no":"42 － 0047","desc":"敷地北の山側から主屋玄関手前の通路にかけて築かれる。延長１１ｍの石段は，平石を敷いた踏段と低い側壁からなり，下方で主屋に向かい緩やかに湾曲する。石段下方に築かれた石塀は，下段を野面石の空積，上段を練積とし，隅石には上下とも切石を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005208"},{"id":"00005207","register_sub_id":"101","register_pk":"106197","name":"梅ヶ谷津偕楽園主屋","kana":"うめがやつかいらくえんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県平戸市明の川内町348","lat":33.34995524,"lng":129.5454368,"geo_status":"db","era":"天保10","year":1839,"year_source":"db","year_min":1839,"year_max":1839,"year_label":null,"structure":"木造2階建、瓦葺、建築面積183㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"42 － 0046","desc":"市北東部，平戸瀬戸を望む高台に位置する。木造，桟瓦葺で，東側中央に玄関を設け，外装は竪板張とする。山の高低差を利用して南向きの２階建とし，海側は開放的なつくりで，山側には茶室などを配する敷地の特徴をいかした別邸建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005207"},{"id":"00004192","register_sub_id":"101","register_pk":"105182","name":"大曲家住宅石段及び石垣","kana":"おおまがりけじゅうたくいしだんおよびいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県平戸市岩の上町1172-1","lat":33.36055309,"lng":129.55565211,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石造、面積61㎡","structure_material":"石造","registered":"2004.06.09(平成16.06.09)","register_no":"42 － 0033","desc":"北西を正面とした主屋前面のアプローチを構成する。石段は直角に折れ曲がる踊り場２箇所をもつ鍵状で，総延長は約２５ｍになる。 踏段は中央に切石，左右に自然石を組み合わせて豊かな表情をつくり，石垣は乱積とする。近世武家屋敷の表構えをよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004192"},{"id":"00004191","register_sub_id":"101","register_pk":"105181","name":"大曲家住宅主屋","kana":"おおまがりけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県平戸市岩の上町1172-1","lat":33.36066388,"lng":129.55544175,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積148㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"42 － 0032","desc":"旧城下の武家地にあり，北西を正面とする。中央は木造２階建，切妻造，平入で，北東面に平屋建で切妻造の座敷を突出し，南西面にたちの高い下屋を設ける。全体に吟味した良材を用い，座敷も床・棚・付書院を備える。武家住宅の系譜を引いた書院造の近代住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004191"},{"id":"00004675","register_sub_id":"101","register_pk":"105665","name":"大曲公家住宅石段及び石垣","kana":"おおまがりただしけじゅうたくいしだんおよびいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県平戸市岩の上町291","lat":33.35941603,"lng":129.55358991,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石造、面積61㎡","structure_material":"石造","registered":"2005.02.09(平成17.02.09)","register_no":"42 － 0039","desc":"屋敷地南側を東西に通る道路から鉤型に折れ曲がって上り主屋玄関の東南方に至る。石段は平均幅２．２ｍで，中途に踊場を設ける。道路沿いと石段両側の石垣は自然石の乱積で高さ約１ｍ，その上に槇の生垣を載せる。平戸城下の武家屋敷地の表構えをよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004675"},{"id":"00004674","register_sub_id":"101","register_pk":"105664","name":"大曲公家住宅主屋","kana":"おおまがりただしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県平戸市岩の上町291","lat":33.35951693,"lng":129.55337434,"geo_status":"db","era":"江戸後期／大正5増改造","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積148㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"42 － 0038","desc":"平戸旧城下の武家屋敷地に位置する。東西棟，切妻造，桟瓦葺の木造２階建で，南・西面に下屋庇を廻す。南面中央東寄りに玄関を設け，西方に８畳座敷と６畳次の間を並べ，座敷の西北方に３畳台目の茶室を配する。平戸藩における茶の伝統を受け継いだ住宅遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004674"},{"id":"00010078","register_sub_id":"101","register_pk":"196225","name":"旧伊東家住宅（四明荘）表門","kana":"きゅういとうけじゅうたく（しめいそう）おもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県島原市新町2-125-1","lat":32.78440176,"lng":130.37069296,"geo_status":"db","era":"明治後期／昭和中期・平成22改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、杉皮葺、間口1.6m","structure_material":"木造","registered":"2014.04.25(平成26.04.25)","register_no":"42 － 0110","desc":"表通りに東面して建つ。宝形造の木柄が細い門で、南西隅の柱を吊柱として、この角を通って敷地に導く構成とする。待合のような風情を持つ数寄屋風の建築で、主屋の座敷や池泉式の庭園に相応しい佇まいの門である。表通りの良好な景観形成にも寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010078"},{"id":"00010077","register_sub_id":"101","register_pk":"196224","name":"旧伊東家住宅（四明荘）主屋","kana":"きゅういとうけじゅうたく（しめいそう）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県島原市新町2-125-1他","lat":32.78433285,"lng":130.37051714,"geo_status":"db","era":"明治後期／大正期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋一部2階建、瓦葺、建築面積96㎡","structure_material":"木造平屋一部2階建","registered":"2014.04.25(平成26.04.25)","register_no":"42 － 0109","desc":"島原市街中心部に位置する。豊かな湧水を利用して庭園が設けられ、中廊下南側の主室は開放的な構成で、湧水池に張出して縁を廻らせる。中廊下北側は、東に玄関を構え、西に台所などを配する。数寄屋意匠の座敷と庭園が調和し、豊かな和風空間を創出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010077"},{"id":"00006070","register_sub_id":"101","register_pk":"107055","name":"旧小川家住宅石垣","kana":"きゅうおがわけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県諫早市飯盛町里811","lat":32.7628174,"lng":129.99813515,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"石造、延長69m","structure_material":"石造","registered":"2006.11.29(平成18.11.29)","register_no":"42 － 0065","desc":"敷地南辺及び東西辺南側を築き，総延長６９ｍの規模で，主屋の敷地を形成する。高さを４ｍとし，南東隅を５ｍと高く築いて庭の築山を築く。平部分を玉石積，隅を切石積として，上方に反りを付ける。自然石を高く積み上げる高度な石工の技術が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006070"},{"id":"00005943","register_sub_id":"101","register_pk":"106928","name":"旧小川家住宅主屋","kana":"きゅうおがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県諫早市飯盛町里811","lat":32.762802,"lng":129.998322,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積225㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"42 － 0064","desc":"石垣によって南側道路から高く築かれた敷地中央に西面して建つ。桁行８間半，梁間５間半の規模で，木造平屋建，寄棟造，桟瓦葺とする。６室を整形に並べ，北西隅に土間をとる。土間脇に式台玄関を設け，つし２階形式で軒を高くし，格式のある外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005943"},{"id":"00011602","register_sub_id":"101","register_pk":"210523","name":"旧長醫家住宅主屋","kana":"きゅうながいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県松浦市星鹿町北久保免字玄道寺498","lat":33.37074,"lng":129.67104,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積264㎡、地下室付","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"42-0129","desc":"御厨港北側の丘上に位置する。木造平屋建、入母屋造で、千鳥破風をつけ変化に富んだ外観を見せる。玄関から西に居室部、南東に客間部を矩折れに配し、北側を女中部屋や台所とする。良材を用いた数寄屋意匠で、ガラス窓や幾何学模様を取り入れ創意が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011602"},{"id":"00009238","register_sub_id":"101","register_pk":"164791","name":"小早川家住宅石塀","kana":"こばやかわけじゅうたくいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県島原市城内2-1013","lat":32.79654044,"lng":130.36514613,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石造、総延長98.7m","structure_material":"石造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地の東.南.西面、及び門と主屋の間に築かれた石塀で、高さ1.6メートル内外、総延長98.7メートルを測る。灰色.桃色.青色などの島原石の切石を亀甲状に巧緻に積み上げ、上部に拳大の割石を積む。島原城下の武家屋敷の特徴をよくとどめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009238"},{"id":"00009236","register_sub_id":"101","register_pk":"164789","name":"小早川家住宅主屋","kana":"こばやかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県島原市城内2-1013","lat":32.79658771,"lng":130.3649146,"geo_status":"db","era":"明治23年","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積194㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"もと上級武家町に占める敷地中央に東面して建つ。建築面積194平方メートル、木造平屋建、入母屋造桟瓦葺である。庭園に面して建つ座敷棟は、良質なつくりの座敷飾りを備えた10畳を主室とする。その北西側に、仏間をもつ玄関棟と、台所棟を雁行形に配置する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009236"},{"id":"00009237","register_sub_id":"101","register_pk":"164790","name":"小早川家住宅門","kana":"こばやかわけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県島原市城内2-1013","lat":32.79663768,"lng":130.36510019,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.6m","structure_material":"木造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地東面の中央北寄りに建ち、主屋玄関正面に門を開く。一間薬医門形式で、桁行2.6メートル梁間1.5メートル、木造、切妻造桟瓦葺である。親柱は見付0.26メートルの五平材で、控柱と貫で固める。質実なつくりの表門で島原の武家屋敷の構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009237"},{"id":"00009239","register_sub_id":"101","register_pk":"164792","name":"小早川家住宅煉瓦塀","kana":"こばやかわけじゅうたくれんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県島原市城内2-1013","lat":32.79673311,"lng":130.36489412,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造、総延長32.1m","structure_material":"煉瓦造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地北面に築かれた煉瓦塀で、道路の傾斜に沿って高さを3段階に変えて積む。厚さは煉瓦半枚分、高さ1.4から1.9メートル、総延長32.1メートルを測り、要所で内側に控壁を設けて補強する。明治期の道路拡幅に伴う築造と伝え、当時の街路景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009239"},{"id":"00000369","register_sub_id":"101","register_pk":"101359","name":"佐藤家住宅主屋","kana":"さとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県長崎市西泊町66","lat":32.73188943,"lng":129.84900494,"geo_status":"db","era":"明治32頃","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建，瓦葺，建築面積106㎡","structure_material":"木造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"42 － 0002","desc":"佐藤家住宅は，長崎湾西側の海岸近くに位置する。東西方向の道路に北面する主屋は，木造２階建で立ちが高い。隣地境界に接する東側に煉瓦造の防火壁を立ち上げる点に特徴がある。伝統的な木造に煉瓦造を巧みに取り入れた珍しい明治中期の住宅建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000369"},{"id":"00000372","register_sub_id":"101","register_pk":"101362","name":"佐藤家住宅石造倉庫Ａ","kana":"さとうけじゅうたくせきぞうそうこえー","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県長崎市西泊町66","lat":32.73186931,"lng":129.84889978,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"石造2階建，瓦葺，建築面積26㎡","structure_material":"石造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"42 － 0005","desc":"主屋の西にあり，南北方向の道路が東西方向の道路に突き当たる３叉路に面する。砂岩を積んで外壁とし，軒蛇腹と妻壁には扁平な形状の「コンニャク煉瓦」とよばれる煉瓦を積む。コンニャク煉瓦を用いた数少ない住宅建築の附属建物として注目される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000372"},{"id":"00000373","register_sub_id":"101","register_pk":"101363","name":"佐藤家住宅石造倉庫Ｂ","kana":"さとうけじゅうたくせきぞうそうこびー","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県長崎市西泊町66","lat":32.73176689,"lng":129.84908176,"geo_status":"db","era":"明治32頃","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"石造2階建，瓦葺，建築面積33㎡","structure_material":"石造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"42 － 0006","desc":"木造附属屋の南にあり，南北方向の道路に面する。形式は石造倉庫Ａと類似するが，煉瓦の形や砂岩の風化等から主屋と同時期の建設と推定される。幕末から明治中期に居留地で多くつくられたがほとんど現存しない石造倉庫の様子を示す遺構として注目に値する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000373"},{"id":"00000371","register_sub_id":"101","register_pk":"101361","name":"佐藤家住宅木造附属屋","kana":"さとうけじゅうたくもくぞうふぞくや","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県長崎市西泊町66","lat":32.73181352,"lng":129.84899671,"geo_status":"db","era":"明治32頃","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積17㎡，袖塀附属","structure_material":"木造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"42 － 0004","desc":"主屋の南西にあり，南北方向の道路に西面する。石塀付の木造平屋建で，南にある石造倉庫Ｂと主屋をつなぐ蔵前の役割を果たしている。東西の外壁を煉瓦造の防火壁とする。防火壁に用いられた煉瓦や木材の風化等から主屋と同時期に建設されたものと推定される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000371"},{"id":"00000370","register_sub_id":"101","register_pk":"101360","name":"佐藤家住宅木造別棟","kana":"さとうけじゅうたくもくぞうべっとう","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県長崎市西泊町66","lat":32.73180346,"lng":129.84912657,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建，瓦葺，建築面積26㎡","structure_material":"木造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"42 － 0003","desc":"主屋の南方に建つ離れ。石造の１階部分の上に木造の２階部分がのる形の建物。太い柱梁を用いる主屋とは対照的に木割りの細い部材を用いた数寄屋風の意匠になる。石造になる数少ない住宅建築であり，用いられた石材の風化等から明治初期の建設と推定される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000370"},{"id":"00011221","register_sub_id":"101","register_pk":"205328","name":"島﨑家住宅主屋","kana":"しまざきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県島原市新町二丁目245-1","lat":32.784847,"lng":130.370846,"geo_status":"db","era":"明治2頃／昭和17・同48改修","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"42 - 0125","desc":"島原城跡の南方に建つ。角地に立つ東西に長い平面の住宅で、西端南面に玄関を開き、南側に廊下を通して北側に居室を並べる。当初は玄関とその北側の客間を含む南北棟部分が建ち、その後仏間から東の東西棟が増築された。島原の往時の町並みを今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011221"},{"id":"00011222","register_sub_id":"101","register_pk":"205329","name":"島﨑家住宅離れ","kana":"しまざきけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県島原市新町二丁目245-2","lat":32.784787,"lng":130.371002,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造平屋建、瓦葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"42 - 0126","desc":"離座敷として建てられたもので、主屋の東側に街路に面して建つ。木造平屋建、妻入で、桟瓦葺。玄関部のほか和室六畳、四畳半、三畳の三室を配し、風呂場・便所を設ける。前面道路脇の水路に接し、城下町島原の景観を形作る建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011222"},{"id":"00010377","register_sub_id":"101","register_pk":"199149","name":"しまばら湧水館（旧三村家住宅）石柱門及び石塀","kana":"しまばらゆうすいかん（きゅうみむらけじゅうたく）いしばしらもんおよびいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県島原市新町2-122","lat":32.78472878,"lng":130.37070531,"geo_status":"db","era":"昭和10年頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"石柱門 石造、間口1.5m 石塀 石造、総延長12m","structure_material":"石柱門 石造","registered":"2014.12.19(平成26.12.19)","register_no":"42-0115","desc":"敷地東面に沿って流れる湧水溝沿いに建つ。南寄りに石柱門を開き、左右に重量感のある石塀をのばす。石塀は切石積基礎上に、長さ約二メートルの横長材を江戸切仕上げとして四段積む。鯉の泳ぐ湧水溝とともに、新町の表通りの景観を形成する要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010377"},{"id":"00010376","register_sub_id":"101","register_pk":"199148","name":"しまばら湧水館（旧三村家住宅）主屋","kana":"しまばらゆうすいかん（きゅうみむらけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県島原市新町2-122他","lat":32.784754,"lng":130.37058,"geo_status":"db","era":"昭和10年頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積158㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"42-0114","desc":"通称水屋敷の点在する区域の敷地に東西棟で建ち、東側に玄関を構える。中廊下式平面で、湧水を導いた庭園に面する南側に接客用座敷を、北側に家族向の部屋を配する。座敷の造作は吟味された良材により丁寧に施工され、庭園との調和が図られた上質な住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010376"},{"id":"00010378","register_sub_id":"101","register_pk":"199150","name":"しまばら湧水館（旧三村家住宅）煉瓦塀","kana":"しまばらゆうすいかん（きゅうみむらけじゅうたく）れんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県島原市新町2-122他","lat":32.78481594,"lng":130.370634,"geo_status":"db","era":"昭和10年頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"煉瓦造、総延長30m","structure_material":"煉瓦造","registered":"2014.12.19(平成26.12.19)","register_no":"42-0116","desc":"敷地東面北寄りから矩折れに、北面西端に延びる煉瓦塀。湧水溝の側石積みの上に、煉瓦を半枚厚で約二メートルの高さに積み上げる。上端には笠木をモルタル塗で表し、敷地内に二・四メートル間隔で煉瓦積の控柱を配する。石塀の多い通りの景観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010378"},{"id":"00003482","register_sub_id":"101","register_pk":"104472","name":"清水家住宅主屋","kana":"しみずけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県島原市上の町865","lat":32.78911366,"lng":130.36945862,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積145㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"42 － 0023","desc":"島原街道の東側，北側に小路が通る角地に西面して建つ。桁行６間半，梁間３間半，切妻造，桟瓦葺，平入の木造２階建で，北側を上手とし，正面全面に１間半の下屋を付す。正面に前庭をつくらない近代の特徴がみられ，島原町家の変遷を知るうえでの指標的事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003482"},{"id":"00014983","register_sub_id":"101","register_pk":"519243","name":"堤内家住宅主屋","kana":"つつみうちけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県島原市先魁町1159-1","lat":32.79341111,"lng":130.36714167,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積132㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"42 - 0139","desc":"島原城跡三の丸の南東部に位置する住宅の主屋。平屋建桟瓦葺で、東南庭に面して部屋を雁行して並べて縁を廻らし、西に玄関、南西に床構え付き座敷、北東に離れを配す。座敷の書院は組子を用いた繊細なつくり。旧城下の歴史的な景観を構成する近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014983"},{"id":"00012851","register_sub_id":"101","register_pk":"367754","name":"堤内家住宅亭","kana":"つつみうちけじゅうたくちん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長崎県","address":"長崎県島原市先魁町1159-3","lat":32.79346778,"lng":130.36714889,"geo_status":"db","era":"昭和8年頃／昭和38年頃改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、茅葺（金属板仮葺）、建築面積40㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"42 － 134","desc":"島原城三の丸南東部に位置する屋敷地東端に建つ離れ。寄棟造茅葺（鉄板仮葺）の平屋建で、南に四畳半の主室、北に三畳二室を配し、有明海を望む主室の東南二面に縁を廻す。各室は趣の異なる数寄屋意匠で整える。城内の屋敷の伝統的な構成を伝える附属建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012851"},{"id":"00014984","register_sub_id":"101","register_pk":"519244","name":"堤内家住宅門及び石塀","kana":"つつみうちけじゅうたくもんおよびいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県島原市先魁町1159-1","lat":32.79331667,"lng":130.36700278,"geo_status":"db","era":"江戸後期／大正後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"門 石造、間口2.8m 石塀 石造、総延長20m","structure_material":"門 石造","registered":"2024.03.06(令和6.03.06)","register_no":"42 - 0140","desc":"島原城跡三の丸南東部に位置する住宅の門及び石塀。門は基礎石上に立つ高さ2・3メートルの石造角柱で表面は粗い割石仕上とする。門両脇に続く石塀は安山岩を切込み矧ぎで積上げ、出隅に反りを付け上部に割石を積む。通りに面し旧城下の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014984"},{"id":"00007701","register_sub_id":"101","register_pk":"108683","name":"長崎市旧市長公舎","kana":"ながさきしきゅうしちょうこうしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県長崎市馬町21-1","lat":32.75201,"lng":129.882202,"geo_status":"db","era":"大正11／昭和42改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積191㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"42 － 0085","desc":"街路に北面して建つ木造２階建の住宅。マンサード屋根で、東西の大棟を寄棟とし、その西端に切妻屋根を付ける。外壁は腰を石積とするテラコッタ貼で、南面にはベイウィンドゥを付け、特徴づける。玄関ホールなどにセセッション風意匠が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007701"},{"id":"00012852","register_sub_id":"101","register_pk":"367755","name":"中村家住宅長屋門","kana":"なかむらけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県島原市萩原一丁目5080","lat":32.78585889,"lng":130.36569,"geo_status":"db","era":"江戸後期／昭和49年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"42 － 135","desc":"島原城の南西方にある住宅の長屋門。街路に東面して建つ入母屋造桟瓦葺の平屋建で、中央に門口を開き、南北に各一室を配する。外壁は真壁造の漆喰塗、正面は腰下見板張、側背面は腰縦板張とする。町年寄宅の旧正門で、城下の町屋敷門の一形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012852"},{"id":"00009865","register_sub_id":"101","register_pk":"195694","name":"永山家住宅隠居屋","kana":"ながやまけじゅうたくいんきょや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県平戸市田助町字浦方98-1","lat":33.39087116,"lng":129.55446447,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階建、瓦葺、建築面積40㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"42 － 0107","desc":"主屋後方に、中庭及び渡廊下を介して海側に配置する。木造二階建、切妻造桟瓦葺で、上下階とも六畳の座敷二間を南北に配し、他を台所などとする。南側には縁を設け、田助浦を望む開放的な構成になる。透彫欄間や箱階段など、内部意匠の細工にも趣向を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009865"},{"id":"00009864","register_sub_id":"101","register_pk":"195693","name":"永山家住宅主屋","kana":"ながやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県平戸市田助町字浦方98-1","lat":33.39092827,"lng":129.55443592,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階建、瓦葺、建築面積149㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"42 － 0106","desc":"田助浦のほぼ中央に位置し、通りに北面する。木造二階建、切妻造桟瓦葺で、正面は腰に簓子下見板を張り、繰形付の持送りで庇を受ける。一階西側と二階に座敷を配し、中央部の吹抜け上方に荷揚用の滑車を残す。隠居屋とともに、港町の景観形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009864"},{"id":"00007419","register_sub_id":"101","register_pk":"108401","name":"西川家住宅主屋","kana":"にしかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県島原市白土町1062","lat":32.781277,"lng":130.36795,"geo_status":"db","era":"明治42／昭和50改修","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積144㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"42 － 0082","desc":"島原街道に東面して建つ。木造つし２階建で、入母屋造桟瓦葺とし、前後に深い下屋庇を設ける。外壁の上部は大壁造で白漆喰仕上げとし、虫籠窓を開ける。下屋正面には出格子を付ける。もとは土間と四間取の床上部から構成された。島原における近代和風住宅の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007419"},{"id":"00005055","register_sub_id":"101","register_pk":"106045","name":"橋口家住宅主屋","kana":"はしぐちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県長崎市新牧野町285","lat":32.85815642,"lng":129.70094372,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造一部石造2階建、瓦葺、建築面積86㎡","structure_material":"木造一部石造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"42 － 0044","desc":"西面する敷地の東側に建つ。桁行６間，梁間４間の規模で，寄棟造，桟瓦葺，木造一部石造２階建で，１階は正面側に床の間付きの板の間及び８畳間を設け，北東隅に台所を設ける。２階を板の間１室とする。西面及び北面を石積みの壁とし，特徴のある造りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005055"},{"id":"00005056","register_sub_id":"101","register_pk":"106046","name":"橋口家住宅倉庫","kana":"はしぐちけじゅうたくそうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県長崎市新牧野町285","lat":32.858074,"lng":129.70092159,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"石造一部木造2階建、瓦葺、建築面積36㎡","structure_material":"石造一部木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"42 － 0045","desc":"敷地南西の隅に北面して建ち，桁行８．４ｍ，梁間４．３ｍの規模で，寄棟造，桟瓦葺，石造２階建である。壁は厚さ０．５ｍ，高さ４ｍで，正面中央幅４．４ｍを木造とし，１間半の引戸を設け，外部に瓦葺の庇を架ける。石造２階建の特異な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005056"},{"id":"00006630","register_sub_id":"101","register_pk":"107613","name":"東山手十三番館住宅主屋","kana":"ひがしやまてじゅうさんばんかんじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県長崎市東山手町甲13","lat":32.738159,"lng":129.873184,"geo_status":"db","era":"明治27頃","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造2階建、瓦葺、建築面積163㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"42 － 0070","desc":"東山手オランダ坂の西側に占める敷地の南寄りに建つ。桁行１４ｍ梁間９．９ｍ、寄棟造桟瓦葺の２階建で、南に寄棟造２階建の付属屋を突き出し、北に庇を設ける。外観は下見板張で、港側の西面にはベランダを設ける。港町長崎の主要な景観要素の一つである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006630"},{"id":"00006631","register_sub_id":"101","register_pk":"107614","name":"東山手十三番館住宅倉庫","kana":"ひがしやまてじゅうさんばんかんじゅうたくそうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県長崎市東山手町甲13","lat":32.738026,"lng":129.873306,"geo_status":"db","era":"明治27頃","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積8.2㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"42 － 0071","desc":"主屋の南側、塀に接して建つ。東西棟の片流れ屋根、桟瓦葺とする。桁行４．８ｍ梁間１．８ｍで、西北隅を隅切する。外壁は下見板張で、北側に片開戸３ヶ所を設け、内部は３室に間仕切り、中央室には窓を穿つ。主屋と一体となって敷地景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006631"},{"id":"00009240","register_sub_id":"101","register_pk":"164793","name":"福重家住宅主屋","kana":"ふくしげけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県東彼杵郡波佐見町井石郷字西ノ前2186-2","lat":33.14097381,"lng":129.90736124,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積406㎡","structure_material":"木造平屋一部2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"木造平屋1部2階建、建築面積406平方メートル、入母屋造桟瓦葺、4周に下屋を廻らす。北側を土間と応接間、南側の床上部を居室として、周囲に縁を廻らす。東側に開放的な構成の座敷を並べ、西側をナンドなどとする。良質なつくりの近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009240"},{"id":"00010241","register_sub_id":"101","register_pk":"198074","name":"碧雲荘（旧熊本家住宅）石垣","kana":"へきうんそう（きゅうくまもとけじゅうたく）いしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県壱岐市石田町印通寺浦字大地330-1","lat":33.74451305,"lng":129.753279,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"石造、総延長123m","structure_material":"石造","registered":"2014.10.07(平成26.10.07)","register_no":"42 － 0113","desc":"敷地南辺東寄りに築かれた石垣で、中央の入口から東隅まで延長約七〇メートル、入口から斜路の北に沿って約四七メートルである。唐津産の玄武岩の切石を整層積とする。表面は瘤出し仕上げである。南東角では高さ約一〇メートルあり、わずかにたるみを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010241"},{"id":"00010239","register_sub_id":"101","register_pk":"198072","name":"碧雲荘（旧熊本家住宅）主屋","kana":"へきうんそう（きゅうくまもとけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県壱岐市石田町石田西触字白水1486-1","lat":33.744912,"lng":129.753306,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積272㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"42 － 0111","desc":"港を望む高台に建つ実業家の本宅で、木造平屋建、入母屋造桟瓦葺。東の玄関脇に和風意匠の応接室を設け、中庭を囲んで、南に畳縁を廻らせた広間座敷一二畳半や数寄屋座敷八畳、北に内玄関等を配す。材工ともに優れ、広間のトコは台目畳三畳大と大振りにつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010239"},{"id":"00010240","register_sub_id":"101","register_pk":"198073","name":"碧雲荘（旧熊本家住宅）門","kana":"へきうんそう（きゅうくまもとけじゅうたく）もん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県壱岐市石田町石田西触字白水1486-1","lat":33.744693,"lng":129.75342,"geo_status":"db","era":"昭和16頃","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造、瓦葺一部銅板葺、間口7.6m、左右袖塀付","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"42 － 0112","desc":"主屋南東に建つ間口三間の腕木門。切妻造桟瓦葺で軒と螻羽は銅板一文字葺とする。本柱は円柱で女梁、男梁で桁を受け、中央間に控柱を立てる。軒は一軒疎垂木。門扉は屋久スギの一枚板を使い、脇間に欄間を入れて潜戸を吊り、両袖塀が付く。雄大な構えの表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010240"},{"id":"00003483","register_sub_id":"101","register_pk":"104473","name":"保里川家住宅主屋","kana":"ほりかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県島原市上の町882","lat":32.79135831,"lng":130.36861645,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積157㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"42 － 0024","desc":"南北に往来する島原街道に西面して建つ。桁行７間半，梁間４間，切妻造，桟瓦葺，平入の木造２階建で，北側を上手とし，正面下手側半分に１間の下屋を下ろし，上手側半分は塀で囲んで前庭をつくる。２階端部の袖壁と１階上手側の入母屋造突出部に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003483"},{"id":"00004477","register_sub_id":"101","register_pk":"105467","name":"益冨家住宅御成門","kana":"ますとみけじゅうたくおなりもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県平戸市生月町壱部浦字崎方182-1","lat":33.39462594,"lng":129.43547168,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口2.5m、石塀延長7.8m付","structure_material":"木造","registered":"2004.11.08(平成16.11.08)","register_no":"42 － 0036","desc":"座敷の北方，敷地東辺の北寄りに南北棟で建つ。切妻造，本瓦葺，１間１戸の薬医門で，主柱８寸５分に５寸５分，冠木９寸５分に６寸５分と全体に木太いのが特徴。北に切石整層積と野石乱層積の石塀が付属する。鯨組と平戸藩との関係を物語る建造物のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004477"},{"id":"00004476","register_sub_id":"101","register_pk":"105466","name":"益冨家住宅座敷","kana":"ますとみけじゅうたくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長崎県","address":"長崎県平戸市生月町壱部浦字崎方182-1","lat":33.39454505,"lng":129.43542766,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積74㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"42 － 0035","desc":"主屋の東北方に南北棟で建つ。桁行４間梁行２間，南を入母屋造，北を切妻造とした木造平屋建で，北・西・南の３面に下屋を廻す。内部は８畳と床・棚・書院付きの８畳座敷２室から成り，３方に縁を巡らす。座敷小襖の落款から天明年間頃まで遡る可能性がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004476"},{"id":"00004475","register_sub_id":"101","register_pk":"105465","name":"益冨家住宅主屋","kana":"ますとみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県平戸市生月町壱部浦字崎方182-1","lat":33.39450948,"lng":129.43527873,"geo_status":"db","era":"嘉永元／昭和12頃改造","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造2階建、瓦葺、建築面積257㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"42 － 0034","desc":"生月島中部東岸壱部浦に，石垣で築いた敷地に建つ。桁行６間梁間５間規模の木造２階建で，東西棟の切妻屋根の四面に下屋を廻し，東面に後補の入母屋造玄関を突き出す。棟梁は井元清之助。改造はあるが，西海捕鯨の隆盛を物語る鯨組主の住宅遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004475"},{"id":"00010380","register_sub_id":"101","register_pk":"199152","name":"松浦家住宅御守堂","kana":"まつらけじゅうたくごしゅどう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"長崎県","address":"長崎県平戸市鏡川町字御舘14イ","lat":33.373575,"lng":129.553034,"geo_status":"db","era":"昭和32年","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積60㎡、登廊付","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"42-0118","desc":"主屋の座敷棟から西に一段高い中腹に位置し、主屋とは登廊でつなぐ。南面して建ち、正面入母屋造、背面切妻造とする妻入建物。正面を板の間、その奥を上段の板の間とし、神棚状の御霊壇を配する。旧藩主家の祖霊を祀る施設で、内部造作にも気品を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010380"},{"id":"00010379","register_sub_id":"101","register_pk":"199151","name":"松浦家住宅主屋","kana":"まつらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"長崎県","address":"長崎県平戸市鏡川町字御舘14イ","lat":33.373521,"lng":129.55329,"geo_status":"db","era":"昭和32年","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造2階建、瓦葺、建築面積292㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"42-0117","desc":"旧平戸藩主松浦家の邸宅。Ｌ字形平面を呈し、東西棟の東端に本玄関と応接室、廊下を介して西に座敷二室を並べ、南北棟に事務室等を配す。主座敷では出入口を欠円形に象り、大胆かつ洗練された和風意匠とする。主や客、使用人の動線を明快に区分した近代住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010379"},{"id":"00005511","register_sub_id":"101","register_pk":"106499","name":"松浦史料博物館（旧松浦詮邸）閑雲亭","kana":"まつらしりょうはくぶつかん（きゅうまつらあきらてい）かんうんてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県平戸市鏡川町12","lat":33.37265486,"lng":129.55182614,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、茅葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"42 － 0059","desc":"敷地西南隅，中門と生垣で囲う一画に位置する。４畳の茶室と６畳の座敷からなる寄棟造，茅葺の木造平屋建。枝付自然木の柱で軒を支える。北側屋根を葺きおろし，雪隠と手水場を備える。天井を張らず，建具を開け放して眺望を楽しむ開放的なつくりが特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005511"},{"id":"00005512","register_sub_id":"101","register_pk":"106500","name":"松浦史料博物館（旧松浦詮邸）閑雲亭待合","kana":"まつらしりょうはくぶつかん（きゅうまつらあきらてい）かんうんていまちあい","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県平戸市鏡川町12","lat":33.37269993,"lng":129.5519219,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造、檜皮葺、面積9.7㎡","structure_material":"木造","registered":"2006.03.27(平成18.03.27)","register_no":"42 － 0060","desc":"閑雲亭の東側に独立の外待合として建つ切妻造，檜皮葺の木造平屋建。枝付自然木の柱を４隅に立て，壁は設けず吹放ちとする。中央の自然石の腰掛は，眺望を考慮して南面して座るように置かれる。閑雲亭と共に屋敷の特色を反映した景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005512"},{"id":"00010535","register_sub_id":"101","register_pk":"199474","name":"吉田家住宅主屋","kana":"よしだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県長崎市宿町665-3","lat":32.758702,"lng":129.935284,"geo_status":"db","era":"明治28／明治43改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階建、瓦葺、建築面積200㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"42 － 0122","desc":"生業であった水車による精米のため、川沿いに宅地を構える。土間玄関と八畳座敷二室を含む略田字形間取りの当初部の西側に、後設の新座敷を張出す。土間まわりの軸部は重厚で、座敷の造作も古風かつ上質である。明治期における住宅形式変遷の一例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010535"},{"id":"00010536","register_sub_id":"101","register_pk":"199475","name":"吉田家住宅長屋門","kana":"よしだけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県長崎市宿町665-3","lat":32.758795,"lng":129.935133,"geo_status":"db","era":"明治24／昭和初期改修","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建、瓦葺、建築面積88㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"42 － 0123","desc":"敷地北辺西寄りに位置し、旧長崎街道に北面する大型の長屋門で、切妻造桟瓦葺。東端を門口とし、西に使用人部屋、牛小屋などを連ねる。門口は間口が広く内法も高く、上部に切妻破風を付け、妻飾に格子を嵌めるなど、屋敷地の入口として格式の高い意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010536"},{"id":"00010534","register_sub_id":"101","register_pk":"202520","name":"料亭春海","kana":"りょうていはるみ","category":"住宅","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県長崎市鍛冶屋町278","lat":32.742056,"lng":129.883293,"geo_status":"db","era":"明治40／昭和13・昭和16・昭和25改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、瓦葺、建築面積244㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"42 － 0121","desc":"崇福寺の西側に所在する。西正面中央に式台玄関を構え、池に面して座敷を雁行させ、二階南側に大広間を配する。各室とも銘木や古木などを巧みに使い風雅な意匠をもつ。書院造を基調とした当初部に随時数寄屋風の各室を加えた料亭建築で、市中の隠の趣を呈す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010534"},{"id":"00001022","register_sub_id":"101","register_pk":"102012","name":"赤坂家石倉","kana":"あかさかけいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県球磨郡山江村大字山田乙567","lat":32.24609334,"lng":130.78163409,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"石造２階建，瓦葺，建築面積240㎡","structure_material":"石造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"43 － 0017","desc":"石切り場として知られる円蔵山産の切石を用いた切妻造，瓦葺の２階建石倉で，標準的な施工になる。両妻壁に倉を建てた家人の名を示す「赤」及び「貞」の文字を造りす。穀物倉庫として利用されており，村内に残る石倉のうちでは一番小さいが最も古い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001022"},{"id":"00013904","register_sub_id":"101","register_pk":"507862","name":"足達家住宅主屋","kana":"あだちけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県阿蘇郡産山村大字大利字大利北向1406","lat":32.97877778,"lng":131.24479444,"geo_status":"db","era":"明治24年／大正元年頃増築","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造平屋一部二階建、鉄板葺、建築面積246㎡","structure_material":"木造平屋一部二階建","registered":"2021.06.24(令和3.06.24)","register_no":"43 － 0184","desc":"豊後街道に北面。平屋一部二階建入母屋造鉄板葺で四周に下屋を廻す。軒はせがい造で下屋は吹寄とし、唐破風造の式台玄関には随所に彫刻を施す。式台から上手に二列七室を配し、北西の座敷は蟻壁を廻すなど格調高い。書院風の構えを有する質の高い農家の主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013904"},{"id":"00016463","register_sub_id":"101","register_pk":"536530","name":"有馬家住宅蔵","kana":"ありまけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県上益城郡益城町大字砥川字宮園2129","lat":32.75463333,"lng":130.81312222,"geo_status":"db","era":"明治21年／令和元年改修","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造2階建、瓦葺、建築面積48㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"43 - 0221","desc":"市街地南方の高台に位置する旧家の米蔵。敷地南に東面する２階建切妻造妻入桟瓦葺で正面に下屋を付す。外壁は漆喰塗で腰は海鼠壁とする。一階は土間で内壁周囲に荷擦木を打ち、二階は板敷で上部に束立と登梁の和小屋を現す。正面妻の菊の鏝絵が目を惹く土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016463"},{"id":"00000492","register_sub_id":"101","register_pk":"101482","name":"今村家住宅","kana":"いまむらけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"江戸","pref":"熊本県","address":"熊本県熊本市南区川尻四丁目790","lat":32.73785401,"lng":130.68105879,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建，瓦葺，建築面積191㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"43 － 0007","desc":"熊本市の南端，加勢川の北岸に近い県道に面して広い間口を構える大型町家。西南戦争の際に薩摩軍の本陣が置かれたと伝える。１階の出格子と２階を低く押さえた外観に特徴があり，西南戦争以前の民家が比較的に多く残る川尻の町でひときわ目をひく建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000492"},{"id":"00005520","register_sub_id":"101","register_pk":"106508","name":"上田家住宅裏門及び塀","kana":"うえだけじゅうたくうらもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県天草市天草町高浜南723","lat":32.37512327,"lng":129.99667273,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"裏門 木造、瓦葺、間口2.1m、塀 木造、瓦葺、延長62m","structure_material":"裏門 木造","registered":"2006.03.27(平成18.03.27)","register_no":"43 － 0085","desc":"裏門は敷地南東隅に位置し，間口２．１ｍの木造の四脚門で，切妻造，桟瓦葺とする。塀は離座敷の南側の庭園と池を囲み，高さ２．５ｍ，切妻造，桟瓦葺の屋根をのせる。総延長６２ｍで，木造を主とするが，南側及び東側の柱を石柱とし，南側には無双窓を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005520"},{"id":"00005518","register_sub_id":"101","register_pk":"106506","name":"上田家住宅表玄関","kana":"うえだけじゅうたくおもてげんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"熊本県","address":"熊本県天草市天草町高浜南723","lat":32.37538415,"lng":129.99656868,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"43 － 0083","desc":"主屋南側に建ち，桁行５間半，梁間２間規模の木造平屋建，切妻造，桟瓦葺とする。西面中央に入母屋造，桟瓦葺の，間口１間半の式台玄関を開く。北端が主屋に，南端が離座敷に接続し，大規模屋敷の表玄関として新設され，屋敷の接客空間の充実過程を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005518"},{"id":"00005516","register_sub_id":"101","register_pk":"106504","name":"上田家住宅主屋","kana":"うえだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県天草市天草町高浜南723","lat":32.3755077,"lng":129.99656021,"geo_status":"db","era":"文化12","year":1815,"year_source":"db","year_min":1815,"year_max":1815,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積467㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"43 － 0081","desc":"桁行１０間，梁間８間規模の木造平屋建で，東西棟の入母屋造，瓦葺とし，南面して建つ。外壁は漆喰塗で腰を下見板張とする。北西隅に炊事場及び物置を，東側背面に浴室等を張出す。江戸時代後期の庄屋宅で，規模及び意匠等，堂々たるつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005516"},{"id":"00005519","register_sub_id":"101","register_pk":"106507","name":"上田家住宅正門","kana":"うえだけじゅうたくせいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県天草市天草町高浜南723","lat":32.3752055,"lng":129.99648665,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造、瓦葺、間口2.5m","structure_material":"木造","registered":"2006.03.27(平成18.03.27)","register_no":"43 － 0084","desc":"主屋玄関の前方，南側敷地境に建つ。棟高３．４メートル，間口２．５メートルの四脚門。切妻造，桟瓦葺で，棟に鳥衾を飾る。幅の異なる２枚の板戸を両開きに開き，片方に潜戸を設ける。簡素なつくりながら，敷地前面の中央に位置し，大規模な屋敷構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005519"},{"id":"00005517","register_sub_id":"101","register_pk":"106505","name":"上田家住宅離座敷","kana":"うえだけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"熊本県","address":"熊本県天草市天草町高浜南723","lat":32.37529859,"lng":129.99662677,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積105㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"43 － 0082","desc":"主屋南側の表玄関南に接続する。東西棟の入母屋造，桟瓦葺で四周に下屋を廻す。座敷１２畳半の四周に広縁を廻し，東面及び南面に切目縁を廻らす。床，棚，書院など良材を用い，繊細で端正なつくり。ガラス戸を多用した開放的側廻りに近代の造形感覚が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005517"},{"id":"00013207","register_sub_id":"101","register_pk":"368309","name":"江藤家住宅主屋","kana":"えとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県菊池郡大津町大字町字尾ノ上169","lat":32.85675833,"lng":130.865975,"geo_status":"db","era":"江戸末期","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積305㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"43 － 0177","desc":"大津町の農村集落にある、在御家人という家格を持つ家の主屋。敷地中央に南面して建つ。木造平屋建で、入母屋造桟瓦葺の大屋根の西側に、角屋が平行して二棟突出する。角屋の間を合いの間で繋ぐ平面形状に特徴があり、当地区の近世農家の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013207"},{"id":"00016626","register_sub_id":"101","register_pk":"574988","name":"大麻家住宅主屋（旧木葉郵便局）","kana":"おおあさけじゅうたくおもや(きゅうこのはゆうびんきょく)","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県玉名郡玉東町大字木葉字上ハ町1132-2","lat":32.91891917,"lng":130.62853889,"geo_status":"db","era":"昭和12年／昭和43年・令和元年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積176㎡","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"43 - 0031","desc":"三池往還沿いに位置する旧家の主屋。平屋建入母屋造東西棟の南西に、二階建入母屋造南北棟を雁行して配し全体桟瓦葺。入隅に式台玄関を設ける。南西棟一階は旧郵便局舎で外壁下見板張や縦長窓を留め、二階は端正な座敷を残す。昭和戦前の地域の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016626"},{"id":"00014303","register_sub_id":"101","register_pk":"509693","name":"大田黒家住宅主屋","kana":"おおたぐろけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県菊池郡大津町大字下町字窪田210","lat":32.85663333,"lng":130.85900833,"geo_status":"db","era":"江戸末期／明治前期・大正13年頃増築・平成12年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積286㎡","structure_material":"木造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"43 - 0188","desc":"阿蘇山麓の農村集落に所在する在御家人の旧宅。入母屋造平入桟瓦葺、二階建で周囲に下屋を廻して南正面に式台を構える。平面は西側を土間、東側を六間取とし、式台脇に客間を張出す複雑な平面をもつ。座敷廻りの欄間や襖絵が内部を華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014303"},{"id":"00014217","register_sub_id":"101","register_pk":"508847","name":"太田黒家住宅主屋","kana":"おおたぐろけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県菊池市重味字中鶴2585-1","lat":33.01638889,"lng":130.87918333,"geo_status":"db","era":"江戸末期／平成9年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積183㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"43 - 0186","desc":"日田街道に位置。２階建切妻造桟瓦葺妻入で４周に下屋を廻す。妻は柱梁形に塗上げ、庇や下屋を雲形の持送りで飾り、腰を海鼠壁とし、外観に意匠を凝らす。中央に式台を設け、内部は西を土間、東を２列６室とし南東に床付座敷。格式ある番所勤務の旧役人宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014217"},{"id":"00014304","register_sub_id":"101","register_pk":"509694","name":"大田黒家住宅蔵","kana":"おおたぐろけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県菊池郡大津町大字下町字窪田210","lat":32.85643056,"lng":130.85908889,"geo_status":"db","era":"大正2年／平成16年改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積58㎡","structure_material":"土蔵造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"43 - 0189","desc":"主屋南側に建つ土蔵。二階建、切妻造妻入桟瓦葺で引戸を建てる。基礎は布状に切石を廻し、元は北面壁のように腰を下見板張、上部は漆喰で塗込めて柱梁形を作る。内部は中央に八寸八分角独立柱を立てて、高い位置に梁を架ける。旧家の家格を示す重要な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014304"},{"id":"00014218","register_sub_id":"101","register_pk":"508848","name":"太田黒家住宅蔵","kana":"おおたぐろけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県菊池市重味字中鶴2585-1","lat":33.01641944,"lng":130.87909167,"geo_status":"db","era":"文久3年(1863)／平成10年改修","year":1863,"year_source":"db","year_min":1863,"year_max":1863,"year_label":null,"structure":"木造2階建、瓦葺、建築面積53㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"43 - 0187","desc":"旧番所役人宅の主屋西に建つ土蔵。桁行４間梁間３間、土蔵造２階建、切妻造桟瓦葺で腰は海鼠壁。北妻面に開けた庇付片開窓がアクセントとなる。南に一間半規模で平屋を張出し味噌蔵とする。東面に引戸の戸口を開け、各階板敷の１室。敷地西辺の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014218"},{"id":"00012259","register_sub_id":"101","register_pk":"353060","name":"大森家住宅観音堂","kana":"おおもりけじゅうたくかんのんどう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"熊本県","address":"熊本県山鹿市山鹿47他","lat":33.013419,"lng":130.689268,"geo_status":"db","era":"昭和32年","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積9.3㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"43-171","desc":"敷地南西側に建つ。宝形造本瓦葺で、正側面に高欄付の切目縁を廻し、正面一間で両折桟唐戸を吊り、他三方は二間で側面には半蔀を吊る。内部後方に仏壇を造り、中央に観音像を安置する。組物は出組で、正面のみ中備蟇股とする。落ち着いた意匠の観音堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012259"},{"id":"00012260","register_sub_id":"101","register_pk":"353061","name":"大森家住宅北塀","kana":"おおもりけじゅうたくきたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県山鹿市山鹿47他","lat":33.013728,"lng":130.689619,"geo_status":"db","era":"昭和15年頃","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造、瓦葺、延長20m","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"43-172","desc":"通りに面して主屋から西へ延びる塀。延長二〇メートル、木造で切石積上に建ち、正面は大壁で軒を蛇腹に仕上げ、内側は真壁で絵様持送り付の腕木で軒桁を受ける。板軒で切妻造、桟瓦葺の屋根を架ける形式を採る。主屋と共に街路の歴史的景観を形成する塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012260"},{"id":"00012258","register_sub_id":"101","register_pk":"353059","name":"大森家住宅蔵","kana":"おおもりけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県山鹿市山鹿47他","lat":33.013315,"lng":130.68968,"geo_status":"db","era":"明治初期／明治後期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積118㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"43-170","desc":"敷地南東隅に建つ。土蔵造二階建、切妻造、桟瓦葺。明治初期の東西棟が建ち、明治後期に南北棟を増築し、Ｌ字型平面となった。一、二階とも一室で、小屋組は登梁形式である。外壁を大壁とするが、柱形や梁形をみせている。旧家の暮らしぶりを伝える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012258"},{"id":"00012257","register_sub_id":"101","register_pk":"353058","name":"大森家住宅主屋","kana":"おおもりけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県山鹿市山鹿47他","lat":33.013642,"lng":130.689631,"geo_status":"db","era":"明治5年／大正13年頃・昭和20年頃増築","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造2階建、瓦葺、建築面積381㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"43-169","desc":"旧菊池往還に北面して建つ。東棟はつし二階建の切妻造平入で、間口六間半と広く軒まで塗込め、腰は亀甲模様の海鼠壁で飾る。大正期に背面に増築し洋風の食堂を設けた。西棟は木造二階建、寄棟造で、内法が高く一間幅の広縁を廻す。上質な造りの近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012257"},{"id":"00012261","register_sub_id":"101","register_pk":"353062","name":"大森家住宅西塀","kana":"おおもりけじゅうたくにしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県山鹿市山鹿47他","lat":33.013555,"lng":130.689386,"geo_status":"db","era":"昭和15年頃","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造、瓦葺、延長10m、勝手口付","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"43-173","desc":"敷地西面に建つ塀。南端に矩折で板戸の勝手口を開く。延長一〇メートル、木造で切石積上に建ち、外側は大壁で軒を蛇腹に仕上げ、内側は真壁で、二間毎に石造の控柱を設けており、絵様持送り付の腕木で軒桁を受ける。庭園からの景観に趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012261"},{"id":"00001319","register_sub_id":"101","register_pk":"102309","name":"岡本家石橋","kana":"おかもとけいしばし","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"熊本県","address":"熊本県菊池郡大津町森256","lat":32.86304031,"lng":130.89321114,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"石造，長さ2.6m，幅員2.5m","structure_material":"石造","registered":"1999.08.23(平成11.08.23)","register_no":"43 － 0034","desc":"表門の正面に位置する小規模な石造桁橋。屋敷地の西面を走る道路と屋敷地との間に設けられた幅の狭い水路に架かる。両端の石材の上面ををわずかに曲線状につくり，屋敷地側に小さな親柱を設けて意匠を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001319"},{"id":"00001312","register_sub_id":"101","register_pk":"102302","name":"岡本家住宅馬屋","kana":"おかもとけじゅうたくうまや","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"low","period":"江戸","pref":"熊本県","address":"熊本県菊池郡大津町森256","lat":32.86301007,"lng":130.89354376,"geo_status":"db","era":"天保11頃／昭和初期改造","year":1840,"year_source":"db","year_min":1840,"year_max":1840,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積34㎡，板塀附属","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"43 － 0027","desc":"岡本家の屋敷地は，西と南に道路が走る角地にあり西面している。馬屋は，屋敷地の南東隅にあり，南側の道路に沿って建つ。道路側に下見板を貼り意匠を整えた建物で，昭和初期頃に２階部分を縮小する等の改造を行ったと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001312"},{"id":"00001316","register_sub_id":"101","register_pk":"102306","name":"岡本家住宅裏門","kana":"おかもとけじゅうたくうらもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県菊池郡大津町森256","lat":32.86298638,"lng":130.89340986,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造薬医門，瓦葺，間口2.0m，板塀附属","structure_material":"木造薬医門","registered":"1999.08.23(平成11.08.23)","register_no":"43 － 0031","desc":"屋敷地の南面，馬屋と南の倉の間に建つ小規模な薬医門。西は南の倉に接し，東は馬屋との間に板塀を設ける。簡略な意匠の門だが，板塀とともに南の倉・馬屋に貼られた壁板と高さをあわせて，道路に面した南側の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001316"},{"id":"00001315","register_sub_id":"101","register_pk":"102305","name":"岡本家住宅表門","kana":"おかもとけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県菊池郡大津町森256","lat":32.86304662,"lng":130.89324042,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造薬医門，瓦葺，間口2.4m，袖塀及び板塀附属","structure_material":"木造薬医門","registered":"1999.08.23(平成11.08.23)","register_no":"43 － 0030","desc":"主屋の西方，屋敷地の正面(西面)にある両袖塀付の薬医門。袖塀の両側に，さらに板塀が接続している。敷地内に引き込んだ位置に建ち，袖塀に屋根を付けて腰に板を貼るなど武家の門らしい構えをつくる。近年修理されたが，主要部材はよく保存されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001315"},{"id":"00001313","register_sub_id":"101","register_pk":"102303","name":"岡本家住宅三階の倉","kana":"おかもとけじゅうたくさんかいのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県菊池郡大津町森256","lat":32.86335145,"lng":130.89348773,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造３階建，瓦葺，建築面積41㎡，板塀附属","structure_material":"木造３階建","registered":"1999.08.23(平成11.08.23)","register_no":"43 － 0028","desc":"屋敷地の北東，主屋の北側に建つ切妻造，妻入，３階建の土蔵。什器や衣類等を収納した。腰になまこ壁を用い，２階部分に水切り瓦を廻すなど，凝った意匠の倉で，岡本家が明治期以降も地主として繁栄したことを示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001313"},{"id":"00001311","register_sub_id":"101","register_pk":"102301","name":"岡本家住宅主屋","kana":"おかもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県菊池郡大津町森256","lat":32.86313041,"lng":130.89347173,"geo_status":"db","era":"天保11","year":1840,"year_source":"db","year_min":1840,"year_max":1840,"year_label":null,"structure":"木造２階建，瓦葺，建築面積349㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"43 － 0026","desc":"岡本家は，大友家の家臣を祖と伝え，その没落後に帰農し幕末期に細川藩の士族となった家である。主屋は，２重屋根や腰のなまこ壁に特徴がある。明治期の増改築がみられるが，主体部の建立年代が棟札によって明らかで，熊本県北部の在郷武家住宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001311"},{"id":"00001317","register_sub_id":"101","register_pk":"102307","name":"岡本家住宅外便所","kana":"おかもとけじゅうたくそとべんじょ","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"low","period":"昭和前","pref":"熊本県","address":"熊本県菊池郡大津町森256","lat":32.862999,"lng":130.893448,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建，瓦葺，建築面積2.１㎡，板塀附属","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"43 － 0032","desc":"主屋と裏門の間に建つ小規模な建物。全体に簡素な形式になるが，足元廻りに煉瓦を貼り，左右の窓の位置をかえ，屋根を食い違い状にして換気が十分にとれるようにするなど，意匠に一定の配慮がなされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001317"},{"id":"00001318","register_sub_id":"101","register_pk":"102308","name":"岡本家住宅塀","kana":"おかもとけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県菊池郡大津町森256","lat":32.86324128,"lng":130.89317467,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"板塀，瓦葺，延長17.2m","structure_material":"板塀","registered":"1999.08.23(平成11.08.23)","register_no":"43 － 0033","desc":"屋敷地の西側を仕切る屋根付の板塀。表門南側に附属する板塀や裏門東に附属する板塀と一連の意匠になるが，基礎に玉石を積んで建て，屋敷地側に石造の控え柱を立てる点は他と異なる。在郷の武家の屋敷構えを示す主要な構成要素のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001318"},{"id":"00001314","register_sub_id":"101","register_pk":"102304","name":"岡本家住宅南の倉","kana":"おかもとけじゅうたくみなみのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県菊池郡大津町森256","lat":32.86297686,"lng":130.89333955,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造２階建，瓦葺，建築面積55㎡，板塀附属","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"43 － 0029","desc":"屋敷地の南西隅に建つ切妻造，平入，２階建の土蔵。三階の倉と比較すると軒に鉢巻を用いないなど簡略な意匠になるが，腰に下見板を貼り，屋敷地境に建つ塀や馬屋と意匠をあわせている。米の貯蔵等に用いられたと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001314"},{"id":"00001320","register_sub_id":"101","register_pk":"102310","name":"岡本家浄化槽","kana":"おかもとけじょうかそう","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"熊本県","address":"熊本県菊池郡大津町森256","lat":32.86304497,"lng":130.8935819,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造，最大高さ4.3m","structure_material":"鉄筋コンクリート造","registered":"1999.08.23(平成11.08.23)","register_no":"43 － 0035","desc":"主屋と馬屋の間，屋敷地東端部に建つ。コンクリート製の筒を上部に積み上げた形で，用水の水（後に井戸水）をポンプアップして炭・砂等で濾過する仕組みである。この地区に多くみられたが現存するものは少なく，生活の近代化を示す工作物として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001320"},{"id":"00014441","register_sub_id":"101","register_pk":"511430","name":"片岡家住宅主屋","kana":"かたおかけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県阿蘇郡西原村大字布田字南道角2108","lat":32.82781389,"lng":130.90263889,"geo_status":"db","era":"明治13年頃／同３８年増築・昭和３０年頃改修","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積129㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"43 - 0197","desc":"阿蘇外輪裾野の農村に所在する在御家人の住宅。つし二階建、入母屋造桟瓦葺、住居の四間取り床上部分で元は東に土間があった。南に四畳半茶室を付す。縁を廻す床付座敷は欄間を多用して開放的。茶室には竹格子窓等の数寄屋意匠を施す。旧家の佇まいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014441"},{"id":"00016619","register_sub_id":"101","register_pk":"574981","name":"木村家住宅オモシ蔵","kana":"きむらけじゅうたくおもしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県熊本市南区田迎一丁目716","lat":32.80323861,"lng":130.70814722,"geo_status":"db","era":"安永4年（1775）／令和5年改修","year":1775,"year_source":"db","year_min":1775,"year_max":1775,"year_label":null,"structure":"木造2階建、瓦葺、建築面積28㎡","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"43 -0224","desc":"敷地の北寄りに南面して建つ納屋。２階建切妻造平入で外壁は下見板張とする。正面の戸口に庇を付し、内部は各階１室で、１階は土間で根太天井を高く張り、二階は板敷で物置とする。小屋組は西寄り独立柱で地棟を受け登梁を架ける。軸部木太く、質実なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016619"},{"id":"00016617","register_sub_id":"101","register_pk":"574979","name":"木村家住宅主屋","kana":"きむらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県熊本市南区田迎一丁目716","lat":32.80323861,"lng":130.70814722,"geo_status":"db","era":"江戸後期／大正後期・平成3年・令和5年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積277㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"43 - 0222","desc":"市街地南方の農村集落に位置する在御家人住宅の主屋。敷地中央に南面して建つ、平屋建寄棟造鉄板葺で全体に乙型の棟をなす。東は土間、西は床上で南西に座敷を配して庭を望む。床・床脇・付書院を構え、ケヤキの一枚板の床板など、上質な座敷を備える主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016617"},{"id":"00016618","register_sub_id":"101","register_pk":"574980","name":"木村家住宅米蔵","kana":"きむらけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県熊本市南区田迎一丁目716","lat":32.80323861,"lng":130.70814722,"geo_status":"db","era":"文化8年（1811）／令和5年改修","year":1811,"year_source":"db","year_min":1811,"year_max":1811,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"43 - 0223","desc":"主屋の南東に西面して建つ米蔵。２階建切妻造平入桟瓦葺、外壁は漆喰塗仕上で簓子下見板を張る。正面は北寄りに戸口に桟瓦葺庇を付し、窓を二箇所設ける。内部は各階１室で１階は土間、２階は板敷、小屋組は登梁形式。敷地南東の景観をつくる大規模な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016618"},{"id":"00012073","register_sub_id":"101","register_pk":"211014","name":"旧青井家住宅主屋","kana":"きゅうあおいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県人吉市上青井町字上青井町116","lat":32.212961,"lng":130.752218,"geo_status":"db","era":"江戸中期／明治33年増築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋一部2階建、瓦葺、建築面積199㎡","structure_material":"木造平屋一部2階建","registered":"2017.10.27(平成29.10.27)","register_no":"43-164","desc":"青井阿蘇神社境内西側の敷地に南北棟で建つ。屋根は緩い起りをもつ入母屋造桟瓦葺で、妻飾を木連格子とし、南、東面に下屋を廻らす。平面は五室ずつ二列並べ、南半に座敷四室を配し、上質な床を備える。神社の社殿と一体的に残る希少な近世の社家住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012073"},{"id":"00012074","register_sub_id":"101","register_pk":"211015","name":"旧青井家住宅西蔵","kana":"きゅうあおいけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県人吉市上青井町字上青井町116","lat":32.213111,"lng":130.752208,"geo_status":"db","era":"弘化4年（1847）","year":1847,"year_source":"db","year_min":1847,"year_max":1847,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積39㎡","structure_material":"土蔵造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"43-165","desc":"主屋北東に東西棟で建ち、桁行五・九メートル、梁間四・〇メートル、土蔵造、切妻造桟瓦葺で、真壁造の蔵前を設ける。外壁は軒先まで塗籠め、南面の中央間に漆喰塗の扉を両開きとし、背面西寄りに小窓を穿つ。主屋に近接し、社家住宅の屋敷構成を伝える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012074"},{"id":"00012075","register_sub_id":"101","register_pk":"211016","name":"旧青井家住宅東蔵","kana":"きゅうあおいけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県人吉市上青井町字上青井町116","lat":32.213136,"lng":130.752297,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"43-166","desc":"西蔵の東隣に南北棟で建ち、桁行六・二メートル、梁間三・九メートル、土蔵造二階建、切妻造桟瓦葺である。布石積基礎上に建ち、外壁を漆喰塗として鉢巻を廻らす。西面に戸口を開いて瓦葺の小庇を付し、両妻面に小窓を穿つ。往時の社頭景観を伝える近世の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012075"},{"id":"00012076","register_sub_id":"101","register_pk":"211017","name":"旧青井家住宅門","kana":"きゅうあおいけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県人吉市上青井町字上青井町116","lat":32.212716,"lng":130.752541,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.9m","structure_material":"木造","registered":"2017.10.27(平成29.10.27)","register_no":"43-167","desc":"敷地南寄りの石段上に南面して構える。間口二・九メートル、四脚門、切妻造桟瓦葺で、板戸両開きとする。五平断面の本柱間に冠木を渡し、男梁と女梁で冠木を挟み、男梁で桁を受ける。軒は一軒で曲率の強い垂木を疎らに配る。大宮司家の格式ある門構えを創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012076"},{"id":"00012853","register_sub_id":"101","register_pk":"367756","name":"旧石井家住宅主屋","kana":"きゅういしいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県玉名郡南関町大字関外目字木屋塚1070-1","lat":33.06156944,"lng":130.54131667,"geo_status":"db","era":"江戸後期／明治19年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積193㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"43 － 175","desc":"町北部の山あいに構えた屋敷地の中央に東面して建つ。正面入母屋造、背面切妻造妻入の一部二階建で、北面東半に平屋建の別棟が雁行して接続する。南に広い土間、北に1列3室を配し、別棟に座敷と次の間を設ける。山間部の上層農家の暮らしを伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012853"},{"id":"00003492","register_sub_id":"101","register_pk":"104482","name":"旧国鉄矢岳駅駅長官舎井戸","kana":"きゅうこくてつやたけえきえきちょうかんしゃいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"熊本県","address":"熊本県人吉市矢岳町字葭ノ本4762","lat":32.10516503,"lng":130.76786523,"geo_status":"db","era":"明治42頃","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"石造、面積0.87㎡","structure_material":"石造","registered":"2003.07.01(平成15.07.01)","register_no":"43 － 0053","desc":"矢岳駅駅長官舎主屋の東側に位置する石造建造物。溶結凝灰岩の直方体切石を用い，内径１．１ｍ，深さ約４．５ｍの規模で築かれたもので，現在でも利用されている。僻地に建設された鉄道駅長官舎施設における生活状況を端的に物語る施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003492"},{"id":"00003491","register_sub_id":"101","register_pk":"104481","name":"旧国鉄矢岳駅駅長官舎主屋","kana":"きゅうこくてつやたけえきえきちょうかんしゃしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県人吉市矢岳町字葭ノ本4762","lat":32.1051235,"lng":130.7677477,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積84㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"43 － 0052","desc":"宮崎県との県境近くＪＲ肥薩線矢岳駅の西方約１１０ｍに位置する旧官舎施設。切妻造，平入で，外壁を簓子下見板張とする。桁行４間半，梁間３間半の東面に，桁行２間分台所部分を張り出す。全国的にも残存例が少ない明治期の鉄道官舎建築のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003491"},{"id":"00016459","register_sub_id":"101","register_pk":"536526","name":"隈田家住宅離れ","kana":"くまだけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県菊池市隈府字町262-1他","lat":32.98231944,"lng":130.81050833,"geo_status":"db","era":"文化15年（1818）／大正後期移築、令和2年改修","year":1818,"year_source":"db","year_min":1818,"year_max":1818,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積83㎡","structure_material":"土蔵造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"43 - 0217","desc":"隈府の中央通りとの境にある商家の離れ。敷地中央に建つ土蔵造二階建切妻造桟瓦葺で、三方に下屋を付す。一階は中央の畳廊下を挟んで、北に六畳と階段室、南に八畳の座敷を配す。座敷は床と床脇を浅く構え、付書院の欄間は、繊細な柳の透彫とした上質な座敷蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016459"},{"id":"00016621","register_sub_id":"101","register_pk":"574983","name":"佐伯家住宅主屋","kana":"さえきけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県阿蘇市波野大字滝水字滝水久保224","lat":32.95208889,"lng":131.12135528,"geo_status":"db","era":"明治13年／昭和50年・令和3年改修","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造及び土蔵造2階一部3階建、瓦葺、建築面積185㎡","structure_material":"木造及び土蔵造2階一部3階建","registered":"2026.02.10(令和8.02.10)","register_no":"43 - 0226","desc":"阿蘇外輪山東側に位置する旧家の主屋。建ちの高い二階建一部三階建で、六間取平面の背面側に一八畳の応接間を配す。一・二階の座敷は床廻りに良材を用い、書院欄間など洗練した意匠。土間側の南半と全体の軒廻りを漆喰で塗込めた、特異な外観が目を惹く主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016621"},{"id":"00016622","register_sub_id":"101","register_pk":"574984","name":"佐伯家住宅蔵","kana":"さえきけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県阿蘇市波野大字滝水字滝水久保224","lat":32.95208889,"lng":131.12135528,"geo_status":"db","era":"明治前期／令和3年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積141㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"43 - 0227","desc":"主屋の南西に東面して建つ米蔵。二階建切妻造平入桟瓦葺で、外壁は漆喰塗で南面は横板張、腰は竪板張とする。正面に戸口を設けて下屋を付す。内部は北東部の土間以外に床板を張る。二階は南北に間仕切り、各室に階段を設ける。屋敷地の景観を担う大型の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016622"},{"id":"00016624","register_sub_id":"101","register_pk":"574986","name":"佐伯家住宅長屋門","kana":"さえきけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県阿蘇市波野大字滝水字滝水久保224","lat":32.95208889,"lng":131.12135528,"geo_status":"db","era":"明治前期／平成4年・令和3年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積185㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"43 - 0029","desc":"敷地正面に構えた、桁行一三間半、梁間三間半の長屋門。木造平屋建切妻造桟瓦葺、背面に下屋を付し、ほか三方は庇を持送る。正面側の腰は板張。東端間を門口とする以外は、厩や肥料小屋、納屋などにあてる。旧家の表構えとして景観に寄与する大規模な長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016624"},{"id":"00016623","register_sub_id":"101","register_pk":"574985","name":"佐伯家住宅味噌蔵","kana":"さえきけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県阿蘇市波野大字滝水字滝水久保224","lat":32.95208889,"lng":131.12135528,"geo_status":"db","era":"明治前期／令和3年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"43 - 0028","desc":"敷地北西端に東面して建つ味噌蔵。平屋建切妻造平入桟瓦葺で、外壁土壁で腰は竪板張。正背面に半間の下屋を付す。内部は二室で各入口を設ける。北室は味噌醤油蔵、南室は竈を設けた味噌つくりの作業場とし梁上を吹放つ。機能的な間取りをもつ作業小屋風の蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016623"},{"id":"00016625","register_sub_id":"101","register_pk":"574987","name":"佐伯家住宅門及び塀","kana":"さえきけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県阿蘇市波野大字滝水字滝水久保224","lat":32.95208889,"lng":131.12135528,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"門 木造、銅板葺、間口1.5m 塀 木造、銅板葺、総延長13m","structure_material":"門 木造","registered":"2026.02.10(令和8.02.10)","register_no":"43 - 0030","desc":"主屋南東の庭を画す門と塀。北寄りに開く門は腕木門、切妻造銅板葺で門口に両開板戸を建て欄間に透彫彫刻を嵌める。塀は総延長１３メートル、切妻造銅板葺。土台に柱を立て、腕木で桁を受ける。壁面はひしぎ竹の胴縁押え。敷地導入部を彩る繊細な門及び塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016625"},{"id":"00014305","register_sub_id":"101","register_pk":"509695","name":"坂本家住宅主屋","kana":"さかもとけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県菊池郡大津町大字下町字窪田190-１","lat":32.85637778,"lng":130.85987222,"geo_status":"db","era":"江戸末期／昭和58年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積263㎡","structure_material":"木造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"43 - 0190","desc":"阿蘇山麓の農村に所在する在御家人の旧宅。主屋は二階建、入母屋造平入桟瓦葺、敷地中央に南面する。平面は広い土間と四間取とし、東側に上質な座敷を角屋で張出し、元は式台を備えた。全体に天井が高く、座敷は貼付壁で飾る等のびやかで上質な大型民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014305"},{"id":"00014306","register_sub_id":"101","register_pk":"509696","name":"坂本家住宅門","kana":"さかもとけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県菊池郡大津町大字下町字窪田190-１","lat":32.856125,"lng":130.85989167,"geo_status":"db","era":"江戸末期／昭和58年・平成30年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.6m、袖塀付","structure_material":"木造","registered":"2022.06.29(令和4.06.29)","register_no":"43 - 0191","desc":"阿蘇山麓の農村に所在する在御家人の屋敷で、主屋正面に位置する表門。間口２・６メートルの薬医門、切妻造桟瓦葺、組物のない簡素なつくりだが正面側に板天井を張り、引戸を建てるのは珍しい。西袖壁には木戸を開く。在御家人の屋敷としての風格を現す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014306"},{"id":"00013901","register_sub_id":"101","register_pk":"507859","name":"作田家住宅主屋","kana":"さくたけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県八代市本町二丁目5-3他","lat":32.50323611,"lng":130.60078056,"geo_status":"db","era":"昭和元年／平成9年頃改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積83㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"43 － 0181","desc":"八代市の中心部に位置。二階建で屋根を東は切妻造、西は入母屋造として桟瓦を葺く。西に下屋、正面に庇を付す。二階はたちが高くガラス戸を間口いっぱいに建て高欄を付す。一階は改造があるが、二階の一二畳大の座敷二室は旧態をよく残す。近代和風の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013901"},{"id":"00013902","register_sub_id":"101","register_pk":"507860","name":"作田家住宅蔵","kana":"さくたけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県八代市本町二丁目5-6","lat":32.50325278,"lng":130.60087222,"geo_status":"db","era":"大正10年／昭和52年頃・平成6年改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造及び木骨レンガ造3階建、瓦葺、建築面積61㎡","structure_material":"木造及び木骨レンガ造3階建","registered":"2021.06.24(令和3.06.24)","register_no":"43 － 0182","desc":"三階建切妻造桟瓦葺。一階は木造軸組の外周にレンガ積を現し、二階以上は木骨煉瓦造の外周をラスモルタルで仕上げて土蔵造風にみせる。内部は各階とも旧は一室だが、一階を飲食店、二階以上を倉庫等に区画。特異な構造持つ三階蔵の姿が通りからも目を引く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013902"}];
